REPLACE INTO `battlemon_moves` (`id`, `internal_name`, `name`, `type`, `move_category`, `power`, `accuracy`, `pp`, `target`, `function_code`, `flags`, `priority`, `effect_chance`, `description`) VALUES
(1, 'MEGAHORN', 'Megahorn', 'BUG', 'Physical', 120, 85, 10, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Using its tough and impressive horn, the user rams into the target with no letup.'),
(2, 'ATTACKORDER', 'Attack Order', 'BUG', 'Physical', 90, 100, 15, 'NearOther', 'None', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'The user calls out its underlings to pummel the target. Critical hits land more easily.'),
(3, 'BUGBUZZ', 'Bug Buzz', 'BUG', 'Special', 90, 100, 10, 'NearOther', 'LowerTargetSpDef1', 'CanProtect,CanMirrorMove,Sound', 0, 10, 'The user vibrates its wings to generate a damaging sound wave. It may also lower the target''s Sp. Def stat.'),
(4, 'FIRSTIMPRESSION', 'First Impression', 'BUG', 'Physical', 90, 100, 10, 'NearOther', 'FailsIfNotUserFirstTurn', 'Contact,CanProtect,CanMirrorMove', 2, 0, 'Although this move has great power, it only works the first turn the user is in battle.'),
(5, 'POLLENPUFF', 'Pollen Puff', 'BUG', 'Special', 90, 100, 15, 'NearOther', 'HealAllyOrDamageFoe', 'CanProtect,CanMirrorMove,Bomb', 0, 0, 'Fires an exploding pollen puff at enemies, or a HP-restoring one at allies.'),
(6, 'LEECHLIFE', 'Leech Life', 'BUG', 'Physical', 80, 100, 10, 'NearOther', 'HealUserByHalfOfDamageDone', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user drains the target''s blood. The user''s HP is restored by half the damage taken by the target.'),
(7, 'LUNGE', 'Lunge', 'BUG', 'Physical', 80, 100, 15, 'NearOther', 'LowerTargetAttack1', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user makes a lunge at the target, attacking with full force. This lowers the target''s Attack stat.'),
(8, 'XSCISSOR', 'X-Scissor', 'BUG', 'Physical', 80, 100, 15, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user slashes at the foe by crossing its scythes or claws as if they were a pair of scissors.'),
(9, 'SIGNALBEAM', 'Signal Beam', 'BUG', 'Special', 75, 100, 15, 'NearOther', 'ConfuseTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The user attacks with a sinister beam of light. It may also confuse the target.'),
(10, 'SKITTERSMACK', 'Skitter Smack', 'BUG', 'Physical', 70, 90, 10, 'NearOther', 'LowerTargetSpAtk1', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user skitters behind the target to attack. This also lowers the target''s Sp. Atk stat.'),
(11, 'UTURN', 'U-turn', 'BUG', 'Physical', 70, 100, 20, 'NearOther', 'SwitchOutUserDamagingMove', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'After making its attack, the user rushes back to switch places with a party Pokémon in waiting.'),
(12, 'STEAMROLLER', 'Steamroller', 'BUG', 'Physical', 65, 100, 20, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove,TramplesMinimize', 0, 30, 'The user crushes its foes by rolling over them. This attack may make the target flinch.'),
(13, 'BUGBITE', 'Bug Bite', 'BUG', 'Physical', 60, 100, 20, 'NearOther', 'UserConsumeTargetBerry', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user bites the target. If the target is holding a Berry, the user eats it and gains its effect.'),
(14, 'SILVERWIND', 'Silver Wind', 'BUG', 'Special', 60, 100, 5, 'NearOther', 'RaiseUserMainStats1', 'CanProtect,CanMirrorMove', 0, 10, 'The foe is attacked with powdery scales blown by wind. It may also raise all the user''s stats.'),
(15, 'FELLSTINGER', 'Fell Stinger', 'BUG', 'Physical', 50, 100, 25, 'NearOther', 'RaiseUserAttack3IfTargetFaints', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'When the user knocks out a target with this move, the user''s Attack stat rises drastically.'),
(16, 'STRUGGLEBUG', 'Struggle Bug', 'BUG', 'Special', 50, 100, 20, 'AllNearFoes', 'LowerTargetSpAtk1', 'CanProtect,CanMirrorMove', 0, 100, 'While resisting, the user attacks the opposing Pokémon. The targets'' Sp. Atk stat is reduced.'),
(17, 'FURYCUTTER', 'Fury Cutter', 'BUG', 'Physical', 40, 95, 20, 'NearOther', 'PowerHigherWithConsecutiveUse', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is slashed with scythes or claws. Its power increases if it hits in succession.'),
(18, 'PINMISSILE', 'Pin Missile', 'BUG', 'Physical', 25, 95, 20, 'NearOther', 'HitTwoToFiveTimes', 'CanProtect,CanMirrorMove', 0, 0, 'Sharp spikes are shot at the target in rapid succession. They hit two to five times in a row.'),
(19, 'TWINEEDLE', 'Twineedle', 'BUG', 'Physical', 25, 100, 20, 'NearOther', 'HitTwoTimesPoisonTarget', 'CanProtect,CanMirrorMove', 0, 20, 'The foe is stabbed twice by a pair of stingers. It may also poison the target.'),
(20, 'INFESTATION', 'Infestation', 'BUG', 'Special', 20, 100, 20, 'NearOther', 'BindTarget', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is infested and unable to flee for four to five turns.'),
(21, 'DEFENDORDER', 'Defend Order', 'BUG', 'Status', 0, 0, 10, 'User', 'RaiseUserDefSpDef1', NULL, 0, 0, 'The user calls out its underlings to shield its body, raising its Defense and Sp. Def stats.'),
(22, 'HEALORDER', 'Heal Order', 'BUG', 'Status', 0, 0, 10, 'User', 'HealUserHalfOfTotalHP', NULL, 0, 0, 'The user calls out its underlings to heal it. The user regains up to half of its max HP.'),
(23, 'POWDER', 'Powder', 'BUG', 'Status', 0, 100, 20, 'NearOther', 'TargetNextFireMoveDamagesTarget', 'CanProtect,CanMirrorMove,Powder', 0, 0, 'The target is covered in a powder that explodes and damages it if it uses a Fire-type move.'),
(24, 'QUIVERDANCE', 'Quiver Dance', 'BUG', 'Status', 0, 0, 20, 'User', 'RaiseUserSpAtkSpDefSpd1', 'Dance', 0, 0, 'The user performs a beautiful dance. It boosts the user''s Sp. Atk, Sp. Def, and Speed stats.'),
(25, 'RAGEPOWDER', 'Rage Powder', 'BUG', 'Status', 0, 0, 20, 'User', 'RedirectAllMovesToUser', 'Powder', 2, 0, 'The user scatters irritating powder to draw attention to itself. Opponents aim only at the user.'),
(26, 'SPIDERWEB', 'Spider Web', 'BUG', 'Status', 0, 0, 10, 'NearOther', 'TrapTargetInBattle', 'CanMirrorMove', 0, 0, 'The user ensnares the target with thin, gooey silk so it can''t flee from battle.'),
(27, 'STICKYWEB', 'Sticky Web', 'BUG', 'Status', 0, 0, 20, 'FoeSide', 'AddStickyWebToFoeSide', NULL, 0, 0, 'Weaves a sticky net around the opposing team, which lowers their Speed stats upon switching in.'),
(28, 'STRINGSHOT', 'String Shot', 'BUG', 'Status', 0, 95, 40, 'AllNearFoes', 'LowerTargetSpeed2', 'CanProtect,CanMirrorMove', 0, 0, 'The foe is bound with silk blown from the user''s mouth. This silk reduces the target''s Speed.'),
(29, 'TAILGLOW', 'Tail Glow', 'BUG', 'Status', 0, 0, 20, 'User', 'RaiseUserSpAtk3', NULL, 0, 0, 'The user stares at flashing lights to focus its mind, drastically raising its Sp. Atk stat.'),
(30, 'HYPERSPACEFURY', 'Hyperspace Fury', 'DARK', 'Physical', 100, 0, 5, 'NearOther', 'HoopaRemoveProtectionsBypassSubstituteLowerUserDef1', 'CanMirrorMove,CannotMetronome', 0, 0, 'Unleashes a barrage of multi-arm attacks, skipping protections. The user''s Defense stat falls.'),
(31, 'FOULPLAY', 'Foul Play', 'DARK', 'Physical', 95, 100, 15, 'NearOther', 'UseTargetAttackInsteadOfUserAttack', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user turns the foe''s power against it. It does more damage the higher the target''s Attack stat.'),
(32, 'FIERYWRATH', 'Fiery Wrath', 'DARK', 'Special', 90, 100, 10, 'AllNearFoes', 'FlinchTarget', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 20, 'The user transforms its wrath into a fire-like aura to attack. This may also make foes flinch.'),
(33, 'DARKESTLARIAT', 'Darkest Lariat', 'DARK', 'Physical', 85, 100, 10, 'NearOther', 'IgnoreTargetDefSpDefEvaStatStages', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user swings both arms and hits the target. Ignores the target''s stat changes.'),
(34, 'NIGHTDAZE', 'Night Daze', 'DARK', 'Special', 85, 95, 10, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove', 0, 40, 'The user lets loose a pitch-black shock wave at its target. It may also lower the target''s accuracy.'),
(35, 'CRUNCH', 'Crunch', 'DARK', 'Physical', 80, 100, 15, 'NearOther', 'LowerTargetDefense1', 'Contact,CanProtect,CanMirrorMove,Biting', 0, 20, 'The user crunches up the target with sharp fangs. It may also lower the target''s Defense stat.'),
(36, 'DARKPULSE', 'Dark Pulse', 'DARK', 'Special', 80, 100, 15, 'Other', 'FlinchTarget', 'CanProtect,CanMirrorMove,Pulse', 0, 20, 'The user releases a horrible aura imbued with dark thoughts. It may also make the target flinch.'),
(37, 'FALSESURRENDER', 'False Surrender', 'DARK', 'Physical', 80, 0, 10, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user pretends to bow its head, but then it stabs the target with its disheveled hair. Never misses.'),
(38, 'JAWLOCK', 'Jaw Lock', 'DARK', 'Physical', 80, 100, 10, 'NearOther', 'TrapUserAndTargetInBattle', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'This move prevents the user and the target from switching out until either of them faints.'),
(39, 'THROATCHOP', 'Throat Chop', 'DARK', 'Physical', 80, 100, 15, 'NearOther', 'DisableTargetSoundMoves', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user attacks the target''s throat. The target cannot use sound-based moves for two turns.'),
(40, 'WICKEDBLOW', 'Wicked Blow', 'DARK', 'Physical', 80, 100, 5, 'NearOther', 'AlwaysCriticalHit', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'Strikes with a fierce blow through mastery of the Dark style. Always results in a critical hit.'),
(41, 'LASHOUT', 'Lash Out', 'DARK', 'Physical', 75, 100, 5, 'NearOther', 'DoublePowerIfUserStatsLoweredThisTurn', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user lashes out to vent its frustration. Power is doubled if its stats dropped this turn.'),
(42, 'NIGHTSLASH', 'Night Slash', 'DARK', 'Physical', 70, 100, 15, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'The user slashes the target the instant an opportunity arises. Critical hits land more easily.'),
(43, 'SUCKERPUNCH', 'Sucker Punch', 'DARK', 'Physical', 70, 100, 5, 'NearOther', 'FailsIfTargetActed', 'Contact,CanProtect,CanMirrorMove', 1, 0, 'This move enables the user to attack first. It fails if the target is not readying an attack, however.'),
(44, 'KNOCKOFF', 'Knock Off', 'DARK', 'Physical', 65, 100, 20, 'NearOther', 'RemoveTargetItem', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user slaps down the target''s held item, preventing that item from being used in the battle.'),
(45, 'ASSURANCE', 'Assurance', 'DARK', 'Physical', 60, 100, 10, 'NearOther', 'DoublePowerIfTargetLostHPThisTurn', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'If the target has already taken some damage in the same turn, this attack''s power is doubled.'),
(46, 'BITE', 'Bite', 'DARK', 'Physical', 60, 100, 25, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove,Biting', 0, 30, 'The target is bitten with viciously sharp fangs. It may make the target flinch.'),
(47, 'BRUTALSWING', 'Brutal Swing', 'DARK', 'Physical', 60, 100, 20, 'AllNearOthers', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user swings its body around violently to inflict damage on everything in its vicinity.'),
(48, 'FEINTATTACK', 'Feint Attack', 'DARK', 'Physical', 60, 0, 20, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user draws up to the foe disarmingly, then throws a sucker punch. It hits without fail.'),
(49, 'THIEF', 'Thief', 'DARK', 'Physical', 60, 100, 25, 'NearOther', 'UserTakesTargetItem', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user attacks and steals the foe''s held item simultaneously. It can''t steal if the user holds an item.'),
(50, 'SNARL', 'Snarl', 'DARK', 'Special', 55, 95, 15, 'AllNearFoes', 'LowerTargetSpAtk1', 'CanProtect,CanMirrorMove,Sound,CannotMetronome', 0, 100, 'The user yells as if it is ranting about something, making the target''s Sp. Atk stat decrease.'),
(51, 'PAYBACK', 'Payback', 'DARK', 'Physical', 50, 100, 10, 'NearOther', 'DoublePowerIfTargetActed', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'If the user moves after the target, this attack''s power will be doubled.'),
(52, 'PURSUIT', 'Pursuit', 'DARK', 'Physical', 40, 100, 20, 'NearOther', 'PursueSwitchingFoe', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'An attack move that inflicts double damage if used on a target that is switching out of battle.'),
(53, 'BEATUP', 'Beat Up', 'DARK', 'Physical', 1, 100, 10, 'NearOther', 'HitOncePerUserTeamMember', 'CanProtect,CanMirrorMove', 0, 0, 'The user gets all the party Pokémon to attack the foe. The more party Pokémon, the more damage.'),
(54, 'FLING', 'Fling', 'DARK', 'Physical', 1, 100, 10, 'NearOther', 'ThrowUserItemAtTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user flings its held item at the target to attack. Its power and effects depend on the item.'),
(55, 'POWERTRIP', 'Power Trip', 'DARK', 'Physical', 1, 100, 10, 'NearOther', 'PowerHigherWithUserPositiveStatStages', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user boasts of its strength. Power increases the more the user''s stats are raised.'),
(56, 'PUNISHMENT', 'Punishment', 'DARK', 'Physical', 1, 100, 5, 'NearOther', 'PowerHigherWithTargetPositiveStatStages', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'This attack''s power increases the more the target has powered up with stat changes.'),
(57, 'DARKVOID', 'Dark Void', 'DARK', 'Status', 0, 50, 10, 'AllNearFoes', 'SleepTargetIfUserDarkrai', 'CanProtect,CanMirrorMove', 0, 0, 'Opposing Pokémon are dragged into a world of total darkness that makes them sleep.'),
(58, 'EMBARGO', 'Embargo', 'DARK', 'Status', 0, 100, 15, 'NearOther', 'StartTargetCannotUseItem', 'CanProtect,CanMirrorMove', 0, 0, 'It prevents the target from using its held item. Its Trainer is also prevented from using items on it.'),
(59, 'FAKETEARS', 'Fake Tears', 'DARK', 'Status', 0, 100, 20, 'NearOther', 'LowerTargetSpDef2', 'CanProtect,CanMirrorMove', 0, 0, 'The user feigns crying to fluster the target, harshly lowering its Sp. Def stat.'),
(60, 'FLATTER', 'Flatter', 'DARK', 'Status', 0, 100, 15, 'NearOther', 'RaiseTargetSpAtk1ConfuseTarget', 'CanProtect,CanMirrorMove', 0, 0, 'Flattery is used to confuse the target. However, it also raises the target''s Sp. Atk stat.'),
(61, 'HONECLAWS', 'Hone Claws', 'DARK', 'Status', 0, 0, 15, 'User', 'RaiseUserAtkAcc1', NULL, 0, 0, 'The user sharpens its claws to boost its Attack stat and accuracy.'),
(62, 'MEMENTO', 'Memento', 'DARK', 'Status', 0, 100, 10, 'NearOther', 'UserFaintsLowerTargetAtkSpAtk2', 'CanProtect,CanMirrorMove', 0, 0, 'The user faints when using this move. In return, it harshly lowers the target''s Attack and Sp. Atk.'),
(63, 'NASTYPLOT', 'Nasty Plot', 'DARK', 'Status', 0, 0, 20, 'User', 'RaiseUserSpAtk2', NULL, 0, 0, 'The user stimulates its brain by thinking bad thoughts. It sharply raises the user''s Sp. Atk.'),
(64, 'OBSTRUCT', 'Obstruct', 'DARK', 'Status', 0, 0, 10, 'User', 'ProtectUserFromDamagingMovesObstruct', NULL, 4, 0, 'The user protects itself from all attacks. Direct contact lowers the attacker''s Defense.'),
(65, 'PARTINGSHOT', 'Parting Shot', 'DARK', 'Status', 0, 100, 20, 'NearOther', 'LowerTargetAtkSpAtk1SwitchOutUser', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'With a parting threat, the user lowers the target''s Attack and Sp. Atk stats. Then it switches out.'),
(66, 'QUASH', 'Quash', 'DARK', 'Status', 0, 100, 15, 'NearOther', 'TargetActsLast', 'CanProtect,CanMirrorMove', 0, 0, 'The user suppresses the target and makes its move go last.'),
(67, 'SNATCH', 'Snatch', 'DARK', 'Status', 0, 0, 10, 'User', 'StealAndUseBeneficialStatusMove', NULL, 4, 0, 'The user steals the effects of any healing or stat-changing move the foe attempts to use.'),
(68, 'SWITCHEROO', 'Switcheroo', 'DARK', 'Status', 0, 100, 10, 'NearOther', 'UserTargetSwapItems', 'CanProtect,CanMirrorMove', 0, 0, 'The user trades held items with the target faster than the eye can follow.'),
(69, 'TAUNT', 'Taunt', 'DARK', 'Status', 0, 100, 20, 'NearOther', 'DisableTargetStatusMoves', 'CanProtect,CanMirrorMove', 0, 0, 'The target is taunted into a rage that allows it to use only attack moves for three turns.'),
(70, 'TOPSYTURVY', 'Topsy-Turvy', 'DARK', 'Status', 0, 0, 20, 'NearOther', 'InvertTargetStatStages', 'CanProtect,CanMirrorMove', 0, 0, 'All stat changes affecting the target turn topsy-turvy and become the opposite of what they were.'),
(71, 'TORMENT', 'Torment', 'DARK', 'Status', 0, 100, 15, 'NearOther', 'DisableTargetUsingSameMoveConsecutively', 'CanProtect,CanMirrorMove', 0, 0, 'The user torments and enrages the foe, making it incapable of using the same move twice in a row.'),
(72, 'ETERNABEAM', 'Eternabeam', 'DRAGON', 'Special', 160, 90, 5, 'NearOther', 'AttackAndSkipNextTurn', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'This is Eternatus''s most powerful attack in its original form. The user can''t move on the next turn.'),
(73, 'DRAGONENERGY', 'Dragon Energy', 'DRAGON', 'Special', 150, 100, 5, 'AllNearFoes', 'PowerHigherWithUserHP', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'Converts life-force into power to attack. The lower the user''s HP, the lower the move''s power.'),
(74, 'ROAROFTIME', 'Roar of Time', 'DRAGON', 'Special', 150, 90, 5, 'NearOther', 'AttackAndSkipNextTurn', 'CanProtect,CanMirrorMove', 0, 0, 'The user blasts the target with power that distorts even time. The user must rest on the next turn.'),
(75, 'DRACOMETEOR', 'Draco Meteor', 'DRAGON', 'Special', 130, 90, 5, 'NearOther', 'LowerUserSpAtk2', 'CanProtect,CanMirrorMove', 0, 0, 'Comets are summoned down from the sky. The attack''s recoil harshly reduces the user''s Sp. Atk stat.'),
(76, 'OUTRAGE', 'Outrage', 'DRAGON', 'Physical', 120, 100, 10, 'RandomNearFoe', 'MultiTurnAttackConfuseUserAtEnd', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user rampages and attacks for two to three turns. It then becomes confused, however.'),
(77, 'CLANGINGSCALES', 'Clanging Scales', 'DRAGON', 'Special', 110, 100, 5, 'AllNearFoes', 'LowerUserDefense1', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user rubs its scales and makes a huge noise. Also lowers the user''s Defense stat.'),
(78, 'COREENFORCER', 'Core Enforcer', 'DRAGON', 'Special', 100, 100, 10, 'AllNearFoes', 'NegateTargetAbilityIfTargetActed', 'CanProtect,CanMirrorMove', 0, 0, 'If the target has already moved this turn, the effect of its Ability is negated.'),
(79, 'DRAGONRUSH', 'Dragon Rush', 'DRAGON', 'Physical', 100, 75, 10, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove,TramplesMinimize', 0, 20, 'The user tackles the foe while exhibiting overwhelming menace. It may also make the target flinch.'),
(80, 'DYNAMAXCANNON', 'Dynamax Cannon', 'DRAGON', 'Special', 100, 100, 5, 'NearOther', 'None', 'CanProtect,CannotMetronome', 0, 0, 'The user unleashes a strong beam from its core.');
REPLACE INTO `battlemon_moves` (`id`, `internal_name`, `name`, `type`, `move_category`, `power`, `accuracy`, `pp`, `target`, `function_code`, `flags`, `priority`, `effect_chance`, `description`) VALUES
(81, 'SPACIALREND', 'Spacial Rend', 'DRAGON', 'Special', 100, 95, 5, 'NearOther', 'None', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'The user tears the target along with the space around it. Critical hits land more easily.'),
(82, 'DRAGONHAMMER', 'Dragon Hammer', 'DRAGON', 'Physical', 90, 100, 15, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user uses its body like a hammer to attack the target and inflict damage.'),
(83, 'DRAGONPULSE', 'Dragon Pulse', 'DRAGON', 'Special', 85, 100, 10, 'Other', 'None', 'CanProtect,CanMirrorMove,Pulse', 0, 0, 'The target is attacked with a shock wave generated by the user''s gaping mouth.'),
(84, 'DRAGONCLAW', 'Dragon Claw', 'DRAGON', 'Physical', 80, 100, 15, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user slashes the target with huge, sharp claws.'),
(85, 'BREAKINGSWIPE', 'Breaking Swipe', 'DRAGON', 'Physical', 60, 100, 15, 'AllNearFoes', 'LowerTargetAttack1', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 100, 'The user swings its tough tail wildly and attacks all foes. This also lowers their Attack stats.'),
(86, 'DRAGONBREATH', 'Dragon Breath', 'DRAGON', 'Special', 60, 100, 20, 'NearOther', 'ParalyzeTarget', 'CanProtect,CanMirrorMove', 0, 30, 'The user exhales a mighty gust that inflicts damage. It may also leave the target with paralysis.'),
(87, 'DRAGONTAIL', 'Dragon Tail', 'DRAGON', 'Physical', 60, 90, 10, 'NearOther', 'SwitchOutTargetDamagingMove', 'Contact,CanProtect,CanMirrorMove', -6, 0, 'The user knocks away the target and drags out another Pokémon in its party. In the wild, the battle ends.'),
(88, 'DRAGONDARTS', 'Dragon Darts', 'DRAGON', 'Physical', 50, 100, 10, 'NearOther', 'HitTwoTimesTargetThenTargetAlly', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks twice using Dreepy. If there are two targets, this move hits each one once.'),
(89, 'DUALCHOP', 'Dual Chop', 'DRAGON', 'Physical', 40, 90, 15, 'NearOther', 'HitTwoTimes', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user attacks its target by hitting it with brutal strikes. The target is hit twice in a row.'),
(90, 'TWISTER', 'Twister', 'DRAGON', 'Special', 40, 100, 20, 'AllNearFoes', 'FlinchTargetDoublePowerIfTargetInSky', 'CanProtect,CanMirrorMove', 0, 20, 'The user whips up a vicious tornado to tear at the opposing team. It may also make targets flinch.'),
(91, 'SCALESHOT', 'Scale Shot', 'DRAGON', 'Physical', 25, 90, 20, 'NearOther', 'HitTwoToFiveTimesRaiseUserSpd1LowerUserDef1', 'CanProtect,CanMirrorMove', 0, 0, 'Attacks by shooting scales two to five times in a row. Boosts the user''s Speed but lowers its Defense.'),
(92, 'DRAGONRAGE', 'Dragon Rage', 'DRAGON', 'Special', 1, 100, 10, 'NearOther', 'FixedDamage40', 'CanProtect,CanMirrorMove', 0, 0, 'This attack hits the target with a shock wave of pure rage. This attack always inflicts 40 HP damage.'),
(93, 'CLANGOROUSSOUL', 'Clangorous Soul', 'DRAGON', 'Status', 0, 0, 5, 'User', 'RaiseUserMainStats1LoseThirdOfTotalHP', 'Sound,CannotMetronome,Dance', 0, 0, 'The user raises all its stats by using some of its HP.'),
(94, 'DRAGONDANCE', 'Dragon Dance', 'DRAGON', 'Status', 0, 0, 20, 'User', 'RaiseUserAtkSpd1', 'Dance', 0, 0, 'The user vigorously performs a mystic, powerful dance that boosts its Attack and Speed stats.'),
(95, 'BOLTSTRIKE', 'Bolt Strike', 'ELECTRIC', 'Physical', 130, 85, 5, 'NearOther', 'ParalyzeTarget', 'Contact,CanProtect,CanMirrorMove', 0, 20, 'The user charges at its foe, surrounding itself with lightning. It may also leave the target paralyzed.'),
(96, 'VOLTTACKLE', 'Volt Tackle', 'ELECTRIC', 'Physical', 120, 100, 15, 'NearOther', 'RecoilThirdOfDamageDealtParalyzeTarget', 'Contact,CanProtect,CanMirrorMove', 0, 10, 'The user electrifies itself, then charges at the foe. It causes considerable damage to the user as well.'),
(97, 'ZAPCANNON', 'Zap Cannon', 'ELECTRIC', 'Special', 120, 50, 5, 'NearOther', 'ParalyzeTarget', 'CanProtect,CanMirrorMove,Bomb', 0, 100, 'The user fires an electric blast like a cannon to inflict damage and cause paralysis.'),
(98, 'AURAWHEEL', 'Aura Wheel', 'ELECTRIC', 'Physical', 110, 100, 10, 'NearOther', 'TypeDependsOnUserMorpekoFormRaiseUserSpeed1', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 100, 'Morpeko attacks and raises its Speed with energy stored in its cheeks. Type changes with the user''s form.'),
(99, 'THUNDER', 'Thunder', 'ELECTRIC', 'Special', 110, 70, 10, 'NearOther', 'ParalyzeTargetAlwaysHitsInRainHitsTargetInSky', 'CanProtect,CanMirrorMove', 0, 30, 'A wicked thunderbolt is dropped on the foe to inflict damage. It may also leave the target paralyzed.'),
(100, 'FUSIONBOLT', 'Fusion Bolt', 'ELECTRIC', 'Physical', 100, 100, 5, 'NearOther', 'DoublePowerAfterFusionFlare', 'CanProtect,CanMirrorMove', 0, 0, 'The user throws down a giant thunderbolt. It does more damage if influenced by an enormous flame.'),
(101, 'PLASMAFISTS', 'Plasma Fists', 'ELECTRIC', 'Physical', 100, 100, 15, 'NearOther', 'NormalMovesBecomeElectric', 'Contact,CanProtect,CanMirrorMove,Punching,CannotMetronome', 0, 0, 'The user attacks with electrically charged fists. Normal-type moves become Electric-type.'),
(102, 'THUNDERBOLT', 'Thunderbolt', 'ELECTRIC', 'Special', 90, 100, 15, 'NearOther', 'ParalyzeTarget', 'CanProtect,CanMirrorMove', 0, 10, 'A strong electric blast is loosed at the target. It may also leave the target with paralysis.'),
(103, 'WILDCHARGE', 'Wild Charge', 'ELECTRIC', 'Physical', 90, 100, 15, 'NearOther', 'RecoilQuarterOfDamageDealt', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user shrouds itself in electricity and smashes into its foe. It also damages the user a little.'),
(104, 'BOLTBEAK', 'Bolt Beak', 'ELECTRIC', 'Physical', 85, 100, 10, 'NearOther', 'DoublePowerIfTargetNotActed', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Stabs the target with an electrified beak. Power is doubled if the user attacks first.'),
