(110, 'RISINGVOLTAGE', 'Rising Voltage', 'ELECTRIC', 'Special', 70, 100, 20, 'NearOther', 'DoublePowerInElectricTerrain', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks with electric voltage rising from the ground. Power is doubled on Electric Terrain.'),
(111, 'VOLTSWITCH', 'Volt Switch', 'ELECTRIC', 'Special', 70, 100, 20, 'NearOther', 'SwitchOutUserDamagingMove', 'CanProtect,CanMirrorMove', 0, 0, 'After making its attack, the user rushes back to switch places with a party Pokémon in waiting.'),
