(118, 'THUNDERSHOCK', 'Thunder Shock', 'ELECTRIC', 'Special', 40, 100, 30, 'NearOther', 'ParalyzeTarget', 'CanProtect,CanMirrorMove', 0, 10, 'A jolt of electricity is hurled at the foe to inflict damage. It may also leave the target with paralysis.'),
(119, 'NUZZLE', 'Nuzzle', 'ELECTRIC', 'Physical', 20, 100, 20, 'NearOther', 'ParalyzeTarget', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user nuzzles its electrified cheeks against the target. This also leaves the target with paralysis.'),
(120, 'ELECTROBALL', 'Electro Ball', 'ELECTRIC', 'Special', 1, 100, 10, 'NearOther', 'PowerHigherWithUserFasterThanTarget', 'CanProtect,CanMirrorMove,Bomb', 0, 0, 'The user hurls an electric orb at the foe. It does more damage the faster the user is.'),
(121, 'CHARGE', 'Charge', 'ELECTRIC', 'Status', 0, 0, 20, 'User', 'RaiseUserSpDef1PowerUpElectricMove', NULL, 0, 0, 'The user boosts the power of the Electric move it uses next. It also raises the user''s Sp. Def stat.'),
(122, 'EERIEIMPULSE', 'Eerie Impulse', 'ELECTRIC', 'Status', 0, 100, 15, 'NearOther', 'LowerTargetSpAtk2', 'CanProtect,CanMirrorMove', 0, 0, 'The user''s body generates an eerie impulse. Harshly lowers the target''s Sp. Atk stat.'),
(123, 'ELECTRICTERRAIN', 'Electric Terrain', 'ELECTRIC', 'Status', 0, 0, 10, 'BothSides', 'StartElectricTerrain', NULL, 0, 0, 'The user electrifies the ground for five turns. Pokémon on the ground no longer fall asleep.'),
(124, 'ELECTRIFY', 'Electrify', 'ELECTRIC', 'Status', 0, 0, 20, 'NearOther', 'TargetMovesBecomeElectric', 'CanProtect,CanMirrorMove', 0, 0, 'If the target uses a move after being electrified, that move becomes Electric-type.'),
(125, 'IONDELUGE', 'Ion Deluge', 'ELECTRIC', 'Status', 0, 0, 25, 'BothSides', 'NormalMovesBecomeElectric', NULL, 1, 0, 'The user disperses electrically charged particles. Normal-type moves become Electric-type.'),
(126, 'MAGNETRISE', 'Magnet Rise', 'ELECTRIC', 'Status', 0, 0, 10, 'User', 'StartUserAirborne', NULL, 0, 0, 'The user levitates using electrically generated magnetism for five turns.'),
(127, 'MAGNETICFLUX', 'Magnetic Flux', 'ELECTRIC', 'Status', 0, 0, 20, 'UserAndAllies', 'RaisePlusMinusUserAndAlliesDefSpDef1', NULL, 0, 0, 'Manipulates magnetic fields to raise the Defense and Sp. Def stats of allies with Plus or Minus Abilities.'),
(128, 'THUNDERWAVE', 'Thunder Wave', 'ELECTRIC', 'Status', 0, 90, 20, 'NearOther', 'ParalyzeTargetIfNotTypeImmune', 'CanProtect,CanMirrorMove', 0, 0, 'A weak electric charge is launched at the target. It causes paralysis if it hits.'),
