(137, 'DRAININGKISS', 'Draining Kiss', 'FAIRY', 'Special', 50, 100, 10, 'NearOther', 'HealUserByThreeQuartersOfDamageDone', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user steals the target''s HP with a kiss. The user''s HP is restored by over half of the damage dealt.'),
(138, 'DISARMINGVOICE', 'Disarming Voice', 'FAIRY', 'Special', 40, 0, 15, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'Letting out a charming cry, the user does emotional damage to foes. This attack never misses.'),
(139, 'FAIRYWIND', 'Fairy Wind', 'FAIRY', 'Special', 40, 100, 30, 'NearOther', 'None', 'CanProtect,CanMirrorMove', 0, 0, 'The user stirs up a fairy wind and strikes the target with it.'),
(140, 'NATURESMADNESS', 'Nature''s Madness', 'FAIRY', 'Special', 1, 90, 10, 'NearOther', 'FixedDamageHalfTargetHP', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user hits the target with the force of nature. It halves the target''s HP.'),
(141, 'AROMATICMIST', 'Aromatic Mist', 'FAIRY', 'Status', 0, 0, 20, 'NearAlly', 'RaiseTargetSpDef1', NULL, 0, 0, 'The user raises the Sp. Def stat of an ally Pokémon by using a mysterious aroma.'),
(142, 'BABYDOLLEYES', 'Baby-Doll Eyes', 'FAIRY', 'Status', 0, 100, 30, 'NearOther', 'LowerTargetAttack1', 'CanProtect,CanMirrorMove', 1, 0, 'The user stares with its baby-doll eyes, which lowers the target''s Attack stat. Always goes first.'),
(143, 'CHARM', 'Charm', 'FAIRY', 'Status', 0, 100, 20, 'NearOther', 'LowerTargetAttack2', 'CanProtect,CanMirrorMove', 0, 0, 'The user charmingly gazes at the foe, making it less wary. The target''s Attack is harshly lowered.'),
(144, 'CRAFTYSHIELD', 'Crafty Shield', 'FAIRY', 'Status', 0, 0, 10, 'UserSide', 'ProtectUserSideFromStatusMoves', NULL, 3, 0, 'The user protects itself and its allies from status moves with a mysterious power.'),
(145, 'DECORATE', 'Decorate', 'FAIRY', 'Status', 0, 0, 15, 'NearOther', 'RaiseTargetAtkSpAtk2', 'CannotMetronome', 0, 0, 'The user sharply raises the target''s Attack and Sp. Atk stats by decorating the target.'),
