(148, 'FLOWERSHIELD', 'Flower Shield', 'FAIRY', 'Status', 0, 0, 10, 'AllBattlers', 'RaiseGrassBattlersDef1', NULL, 0, 0, 'The user raises the Defense stats of all Grass-type Pokémon in battle with a mysterious power.'),
