(189, 'COUNTER', 'Counter', 'FIGHTING', 'Physical', 1, 100, 20, 'None', 'CounterPhysicalDamage', 'Contact,CanProtect', -5, 0, 'A retaliation move that counters any physical attack, inflicting double the damage taken.'),
