(191, 'LOWKICK', 'Low Kick', 'FIGHTING', 'Physical', 1, 100, 20, 'NearOther', 'PowerHigherWithTargetWeight', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A powerful low kick that makes the foe fall over. It inflicts greater damage on heavier foes.'),
(192, 'REVERSAL', 'Reversal', 'FIGHTING', 'Physical', 1, 100, 15, 'NearOther', 'PowerLowerWithUserHP', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'An all-out attack that becomes more powerful the less HP the user has.'),
