(200, 'QUICKGUARD', 'Quick Guard', 'FIGHTING', 'Status', 0, 0, 15, 'UserSide', 'ProtectUserSideFromPriorityMoves', NULL, 3, 0, 'The user protects itself and its allies from priority moves. If may fail if used in succession.'),
(201, 'VCREATE', 'V-create', 'FIRE', 'Physical', 180, 95, 5, 'NearOther', 'LowerUserDefSpDefSpd1', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'With a fiery forehead, the user hurls itself at the foe. It lowers the user''s Defense, Sp. Def, and Speed.'),
(202, 'BLASTBURN', 'Blast Burn', 'FIRE', 'Special', 150, 90, 5, 'NearOther', 'AttackAndSkipNextTurn', 'CanProtect,CanMirrorMove', 0, 0, 'The target is razed by a fiery explosion. The user must rest on the next turn, however.'),
(203, 'ERUPTION', 'Eruption', 'FIRE', 'Special', 150, 100, 5, 'AllNearFoes', 'PowerHigherWithUserHP', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks in an explosive fury. The lower the user''s HP, the less powerful this attack becomes.'),
(204, 'MINDBLOWN', 'Mind Blown', 'FIRE', 'Special', 150, 100, 5, 'AllNearOthers', 'UserLosesHalfOfTotalHPExplosive', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user attacks everything by causing its own head to explode. This also damages the user.'),
(205, 'SHELLTRAP', 'Shell Trap', 'FIRE', 'Special', 150, 100, 5, 'AllNearFoes', 'UsedAfterUserTakesPhysicalDamage', 'CanProtect', -3, 0, 'The user sets a shell trap. If it is hit by a physical move, the trap explodes and hurt the attacker.'),
(206, 'BLUEFLARE', 'Blue Flare', 'FIRE', 'Special', 130, 85, 5, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 20, 'The user attacks by engulfing the foe in a beautiful, yet intense, blue flame. It may also burn the foe.'),
(207, 'BURNUP', 'Burn Up', 'FIRE', 'Special', 130, 100, 5, 'NearOther', 'UserLosesFireType', 'CanProtect,CanMirrorMove,ThawsUser', 0, 0, 'To inflict massive damage, the user burns itself out. The user will no longer be Fire type.'),
(208, 'OVERHEAT', 'Overheat', 'FIRE', 'Special', 130, 90, 5, 'NearOther', 'LowerUserSpAtk2', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks the target at full power. The attack''s recoil sharply reduces the user''s Sp. Atk stat.'),
(209, 'FLAREBLITZ', 'Flare Blitz', 'FIRE', 'Physical', 120, 100, 15, 'NearOther', 'RecoilThirdOfDamageDealtBurnTarget', 'Contact,CanProtect,CanMirrorMove,ThawsUser', 0, 10, 'The user cloaks itself in fire and charges at the foe. The user also takes damage and may burn the target.'),
(210, 'PYROBALL', 'Pyro Ball', 'FIRE', 'Physical', 120, 90, 5, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove,ThawsUser,Bomb,CannotMetronome', 0, 10, 'Attacks by igniting a small stone and launching it as a fiery ball. May also burn the target.'),
(211, 'FIREBLAST', 'Fire Blast', 'FIRE', 'Special', 110, 85, 5, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The foe is attacked with an intense blast of all-consuming fire. It may also leave the target with a burn.'),
(212, 'FUSIONFLARE', 'Fusion Flare', 'FIRE', 'Special', 100, 100, 5, 'NearOther', 'DoublePowerAfterFusionBolt', 'CanProtect,CanMirrorMove,ThawsUser', 0, 0, 'The user brings down a giant flame. It does more damage if influenced by an enormous thunderbolt.'),
(213, 'INFERNO', 'Inferno', 'FIRE', 'Special', 100, 50, 5, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 100, 'The user attacks by engulfing the target in an intense fire. It leaves the target with a burn.'),
(214, 'MAGMASTORM', 'Magma Storm', 'FIRE', 'Special', 100, 75, 5, 'NearOther', 'BindTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The target becomes trapped within a maelstrom of fire that rages for four to five turns.'),
(215, 'SACREDFIRE', 'Sacred Fire', 'FIRE', 'Physical', 100, 95, 5, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove,ThawsUser', 0, 50, 'The target is razed with a mystical fire of great intensity. It may also leave the target with a burn.'),
(216, 'SEARINGSHOT', 'Searing Shot', 'FIRE', 'Special', 100, 100, 5, 'AllNearOthers', 'BurnTarget', 'CanProtect,CanMirrorMove,Bomb', 0, 30, 'An inferno of scarlet flames torches everything around the user. It may leave the foe with a burn.'),
(217, 'HEATWAVE', 'Heat Wave', 'FIRE', 'Special', 95, 90, 10, 'AllNearFoes', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The user attacks by exhaling hot breath on the opposing team. It may also leave targets with a burn.'),
(218, 'FLAMETHROWER', 'Flamethrower', 'FIRE', 'Special', 90, 100, 15, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The target is scorched with an intense blast of fire. It may also leave the target with a burn.'),
(219, 'BLAZEKICK', 'Blaze Kick', 'FIRE', 'Physical', 85, 90, 10, 'NearOther', 'BurnTarget', 'Contact,CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 10, 'The user launches a kick with a high critical-hit ratio. It may also leave the target with a burn.'),
(220, 'FIERYDANCE', 'Fiery Dance', 'FIRE', 'Special', 80, 100, 10, 'NearOther', 'RaiseUserSpAtk1', 'CanProtect,CanMirrorMove,Dance', 0, 50, 'Cloaked in flames, the user dances and flaps its wings. It may also raise the user''s Sp. Atk stat.'),
(221, 'FIRELASH', 'Fire Lash', 'FIRE', 'Physical', 80, 100, 15, 'NearOther', 'LowerTargetDefense1', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user strikes the target with a burning lash. This also lowers the target''s Defense stat.'),
(222, 'FIREPLEDGE', 'Fire Pledge', 'FIRE', 'Special', 80, 100, 10, 'NearOther', 'FirePledge', 'CanProtect,CanMirrorMove', 0, 0, 'A column of fire hits opposing Pokémon. When used with its Grass equivalent, it makes a sea of fire.'),
(223, 'LAVAPLUME', 'Lava Plume', 'FIRE', 'Special', 80, 100, 15, 'AllNearOthers', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 30, 'An inferno of scarlet flames torches everything around the user. It may leave targets with a burn.'),
(224, 'FIREPUNCH', 'Fire Punch', 'FIRE', 'Physical', 75, 100, 15, 'NearOther', 'BurnTarget', 'Contact,CanProtect,CanMirrorMove,Punching', 0, 10, 'The target is punched with a fiery fist. It may leave the target with a burn.'),
(225, 'MYSTICALFIRE', 'Mystical Fire', 'FIRE', 'Special', 75, 100, 10, 'NearOther', 'LowerTargetSpAtk1', 'CanProtect,CanMirrorMove', 0, 100, 'The user attacks by breathing a special, hot fire. This also lowers the target''s Sp. Atk stat.'),
(226, 'BURNINGJEALOUSY', 'Burning Jealousy', 'FIRE', 'Special', 70, 100, 5, 'AllNearFoes', 'BurnTargetIfTargetStatsRaisedThisTurn', 'CanProtect,CanMirrorMove', 0, 100, 'The user attacks with energy from jealousy. This burns all foes that had their stats boosted this turn.'),
(227, 'FLAMEBURST', 'Flame Burst', 'FIRE', 'Special', 70, 100, 15, 'NearOther', 'DamageTargetAlly', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks the foe with a bursting flame. It also damages Pokémon next to the target.'),
(228, 'FIREFANG', 'Fire Fang', 'FIRE', 'Physical', 65, 95, 15, 'NearOther', 'BurnFlinchTarget', 'Contact,CanProtect,CanMirrorMove,Biting', 0, 101, 'The user bites with flame-cloaked fangs. It may also make the target flinch or leave it burned.'),
(229, 'FLAMEWHEEL', 'Flame Wheel', 'FIRE', 'Physical', 60, 100, 25, 'NearOther', 'BurnTarget', 'Contact,CanProtect,CanMirrorMove,ThawsUser', 0, 10, 'The user cloaks itself in fire and charges at the target. It may also leave the target with a burn.'),
(230, 'INCINERATE', 'Incinerate', 'FIRE', 'Special', 60, 100, 15, 'AllNearFoes', 'DestroyTargetBerryOrGem', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks the foe with fire. The target''s held Berry becomes burnt up and unusable.'),
(231, 'FLAMECHARGE', 'Flame Charge', 'FIRE', 'Physical', 50, 100, 20, 'NearOther', 'RaiseUserSpeed1', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user cloaks itself in flame and attacks. Building up more power, it raises the user''s Speed stat.'),
(232, 'EMBER', 'Ember', 'FIRE', 'Special', 40, 100, 25, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The target is attacked with small flames. It may also leave the target with a burn.'),
(233, 'FIRESPIN', 'Fire Spin', 'FIRE', 'Special', 35, 85, 15, 'NearOther', 'BindTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The target becomes trapped within a fierce vortex of fire that rages for four to five turns.'),
(234, 'HEATCRASH', 'Heat Crash', 'FIRE', 'Physical', 1, 100, 10, 'NearOther', 'PowerHigherWithUserHeavierThanTarget', 'Contact,CanProtect,CanMirrorMove,TramplesMinimize', 0, 0, 'The user slams the foe with its flaming body. The heavier the user is, the greater the damage.'),
(235, 'SUNNYDAY', 'Sunny Day', 'FIRE', 'Status', 0, 0, 5, 'BothSides', 'StartSunWeather', NULL, 0, 0, 'The user intensifies the sun for five turns, powering up Fire-type moves.'),
(236, 'WILLOWISP', 'Will-O-Wisp', 'FIRE', 'Status', 0, 85, 15, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user shoots a sinister, bluish-white flame at the target to inflict a burn.'),
(237, 'SKYATTACK', 'Sky Attack', 'FLYING', 'Physical', 140, 90, 5, 'Other', 'TwoTurnAttackFlinchTarget', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 30, 'A second-turn attack move where critical hits land more easily. It may also make the target flinch.'),
(238, 'BRAVEBIRD', 'Brave Bird', 'FLYING', 'Physical', 120, 100, 15, 'Other', 'RecoilThirdOfDamageDealt', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user tucks in its wings and charges from a low altitude. The user also takes serious damage.'),
(239, 'DRAGONASCENT', 'Dragon Ascent', 'FLYING', 'Physical', 120, 100, 5, 'NearOther', 'LowerUserDefSpDef1', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user soars upward and drops at high speeds. Its Defense and Sp. Def stats are lowered.'),
(240, 'HURRICANE', 'Hurricane', 'FLYING', 'Special', 110, 70, 10, 'Other', 'ConfuseTargetAlwaysHitsInRainHitsTargetInSky', 'CanProtect,CanMirrorMove', 0, 30, 'The user wraps its foe in a fierce wind that flies up into the sky. It may also confuse the foe.');
