(241, 'AEROBLAST', 'Aeroblast', 'FLYING', 'Special', 100, 95, 5, 'Other', 'None', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'A vortex of air is shot at the target to inflict damage. Critical hits land more easily.'),
(242, 'BEAKBLAST', 'Beak Blast', 'FLYING', 'Physical', 100, 100, 15, 'NearOther', 'BurnAttackerBeforeUserActs', 'CanProtect,Bomb', -3, 0, 'The user heats up its beak before attacking. Making contact in this time results in a burn.'),
(243, 'FLY', 'Fly', 'FLYING', 'Physical', 90, 95, 15, 'Other', 'TwoTurnAttackInvulnerableInSky', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user soars, then strikes on the second turn. It can also be used for flying to any familiar town.'),
(244, 'BOUNCE', 'Bounce', 'FLYING', 'Physical', 85, 85, 5, 'Other', 'TwoTurnAttackInvulnerableInSkyParalyzeTarget', 'Contact,CanProtect,CanMirrorMove', 0, 30, 'The user bounces up high, then drops on the foe on the second turn. It may also paralyze the foe.'),
(245, 'DRILLPECK', 'Drill Peck', 'FLYING', 'Physical', 80, 100, 20, 'Other', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A corkscrewing attack with the sharp beak acting as a drill.'),
(246, 'OBLIVIONWING', 'Oblivion Wing', 'FLYING', 'Special', 80, 100, 10, 'Other', 'HealUserByThreeQuartersOfDamageDone', 'CanProtect,CanMirrorMove', 0, 0, 'The user absorbs its target''s HP. The user''s HP is restored by over half of the damage dealt.'),
(247, 'AIRSLASH', 'Air Slash', 'FLYING', 'Special', 75, 95, 15, 'Other', 'FlinchTarget', 'CanProtect,CanMirrorMove', 0, 30, 'The user attacks with a blade of air that slices even the sky. It may also make the target flinch.'),
