(259, 'FEATHERDANCE', 'Feather Dance', 'FLYING', 'Status', 0, 100, 15, 'NearOther', 'LowerTargetAttack2', 'CanProtect,CanMirrorMove,Dance', 0, 0, 'The user covers the target''s body with a mass of down that harshly lowers its Attack stat.'),
(260, 'MIRRORMOVE', 'Mirror Move', 'FLYING', 'Status', 0, 0, 20, 'NearOther', 'UseLastMoveUsedByTarget', NULL, 0, 0, 'The user counters the target by mimicking the target''s last move.'),
