(280, 'CONFUSERAY', 'Confuse Ray', 'GHOST', 'Status', 0, 100, 10, 'NearOther', 'ConfuseTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The target is exposed to a sinister ray that triggers confusion.'),
