(300, 'GRASSPLEDGE', 'Grass Pledge', 'GRASS', 'Special', 80, 100, 10, 'NearOther', 'GrassPledge', 'CanProtect,CanMirrorMove', 0, 0, 'A column of grass hits the foes. When used with its water equivalent, it creates a vast swamp.'),
(301, 'GRAVAPPLE', 'Grav Apple', 'GRASS', 'Physical', 80, 100, 10, 'NearOther', 'LowerTargetDefense1PowersUpInGravity', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 100, 'The user inflicts damage by dropping an apple from high above. This also lowers the target''s Defense.'),
(302, 'SEEDBOMB', 'Seed Bomb', 'GRASS', 'Physical', 80, 100, 15, 'NearOther', 'None', 'CanProtect,CanMirrorMove,Bomb', 0, 0, 'The user slams a barrage of hard-shelled seeds down on the target from above.'),
(303, 'GIGADRAIN', 'Giga Drain', 'GRASS', 'Special', 75, 100, 10, 'NearOther', 'HealUserByHalfOfDamageDone', 'CanProtect,CanMirrorMove', 0, 0, 'A nutrient-draining attack. The user''s HP is restored by half the damage taken by the target.'),
(304, 'HORNLEECH', 'Horn Leech', 'GRASS', 'Physical', 75, 100, 10, 'NearOther', 'HealUserByHalfOfDamageDone', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user drains the foe''s energy with its horns. The user''s HP is restored by half the damage inflicted.'),
(305, 'GRASSYGLIDE', 'Grassy Glide', 'GRASS', 'Physical', 70, 100, 20, 'NearOther', 'HigherPriorityInGrassyTerrain', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Gliding on the ground, the user attacks the target. This move always goes first on Grassy Terrain.'),
(306, 'TROPKICK', 'Trop Kick', 'GRASS', 'Physical', 70, 100, 15, 'NearOther', 'LowerTargetAttack1', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'The user lands an intense tropical kick on the target. This also lowers the target''s Attack stat.'),
(307, 'LEAFTORNADO', 'Leaf Tornado', 'GRASS', 'Special', 65, 90, 10, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove', 0, 50, 'The user attacks its foe by encircling it in sharp leaves. This attack may also lower the foe''s accuracy.'),
(308, 'MAGICALLEAF', 'Magical Leaf', 'GRASS', 'Special', 60, 0, 20, 'NearOther', 'None', 'CanProtect,CanMirrorMove', 0, 0, 'The user scatters curious leaves that chase the target. This attack will not miss.'),
(309, 'NEEDLEARM', 'Needle Arm', 'GRASS', 'Physical', 60, 100, 15, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove', 0, 30, 'The user attacks by wildly swinging its thorny arms. It may also make the target flinch.'),
(310, 'RAZORLEAF', 'Razor Leaf', 'GRASS', 'Physical', 55, 95, 25, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'Sharp-edged leaves are launched to slash at the opposing team. Critical hits land more easily.'),
(311, 'VINEWHIP', 'Vine Whip', 'GRASS', 'Physical', 45, 100, 25, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is struck with slender, whiplike vines to inflict damage.'),
(312, 'BRANCHPOKE', 'Branch Poke', 'GRASS', 'Physical', 40, 100, 40, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user attacks the target by poking it with a sharply pointed branch.'),
(313, 'LEAFAGE', 'Leafage', 'GRASS', 'Physical', 40, 100, 40, 'NearOther', 'None', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks by pelting the target with leaves.'),
(314, 'MEGADRAIN', 'Mega Drain', 'GRASS', 'Special', 40, 100, 15, 'NearOther', 'HealUserByHalfOfDamageDone', 'CanProtect,CanMirrorMove', 0, 0, 'A nutrient-draining attack. The user''s HP is restored by half the damage taken by the target.'),
(315, 'SNAPTRAP', 'Snap Trap', 'GRASS', 'Physical', 35, 100, 15, 'NearOther', 'BindTarget', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user snares the target in a snap trap for four to five turns.'),
(316, 'BULLETSEED', 'Bullet Seed', 'GRASS', 'Physical', 25, 100, 30, 'NearOther', 'HitTwoToFiveTimes', 'CanProtect,CanMirrorMove,Bomb', 0, 0, 'The user forcefully shoots seeds at the target. Two to five seeds are shot in rapid succession.'),
(317, 'ABSORB', 'Absorb', 'GRASS', 'Special', 20, 100, 25, 'NearOther', 'HealUserByHalfOfDamageDone', 'CanProtect,CanMirrorMove', 0, 0, 'A nutrient-draining attack. The user''s HP is restored by half the damage taken by the target.'),
(318, 'GRASSKNOT', 'Grass Knot', 'GRASS', 'Special', 1, 100, 20, 'NearOther', 'PowerHigherWithTargetWeight', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user snares the target with grass and trips it. The heavier the target, the greater the damage.'),
(319, 'AROMATHERAPY', 'Aromatherapy', 'GRASS', 'Status', 0, 0, 5, 'UserAndAllies', 'CureUserPartyStatus', NULL, 0, 0, 'The user releases a soothing scent that heals all status problems affecting the user''s party.'),
(320, 'COTTONGUARD', 'Cotton Guard', 'GRASS', 'Status', 0, 0, 10, 'User', 'RaiseUserDefense3', NULL, 0, 0, 'The user protects itself by wrapping its body in soft cotton, drastically raising its Defense stat.');
REPLACE INTO `battlemon_moves` (`id`, `internal_name`, `name`, `type`, `move_category`, `power`, `accuracy`, `pp`, `target`, `function_code`, `flags`, `priority`, `effect_chance`, `description`) VALUES
(321, 'COTTONSPORE', 'Cotton Spore', 'GRASS', 'Status', 0, 100, 40, 'AllNearFoes', 'LowerTargetSpeed2', 'CanProtect,CanMirrorMove,Powder', 0, 0, 'The user releases cotton-like spores that cling to the foe, harshly reducing its Speed stat.'),
(322, 'FORESTSCURSE', 'Forest''s Curse', 'GRASS', 'Status', 0, 100, 20, 'NearOther', 'AddGrassTypeToTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user puts a forest curse on the target. The target is now Grass type as well.'),
(323, 'GRASSWHISTLE', 'Grass Whistle', 'GRASS', 'Status', 0, 55, 15, 'NearOther', 'SleepTarget', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user plays a pleasant melody that lulls the target into a deep sleep.'),
(324, 'GRASSYTERRAIN', 'Grassy Terrain', 'GRASS', 'Status', 0, 0, 10, 'BothSides', 'StartGrassyTerrain', NULL, 0, 0, 'The user turns the ground to grass for five turns. Grounded Pokémon restore a little HP every turn.'),
(325, 'INGRAIN', 'Ingrain', 'GRASS', 'Status', 0, 0, 20, 'User', 'StartHealUserEachTurnTrapUserInBattle', NULL, 0, 0, 'The user lays roots that restore its HP on every turn. Because it is rooted, it can''t switch out.'),
(326, 'JUNGLEHEALING', 'Jungle Healing', 'GRASS', 'Status', 0, 0, 10, 'UserAndAllies', 'HealUserAndAlliesQuarterOfTotalHPCureStatus', 'CannotMetronome', 0, 0, 'The user becomes one with the jungle, and restores HP and cures status conditions of itself and allies.'),
(327, 'LEECHSEED', 'Leech Seed', 'GRASS', 'Status', 0, 90, 10, 'NearOther', 'StartLeechSeedTarget', 'CanProtect,CanMirrorMove', 0, 0, 'A seed is planted on the target. It steals some HP from the target every turn.'),
(328, 'SLEEPPOWDER', 'Sleep Powder', 'GRASS', 'Status', 0, 75, 15, 'NearOther', 'SleepTarget', 'CanProtect,CanMirrorMove,Powder', 0, 0, 'The user scatters a big cloud of sleep-inducing dust around the target.'),
(329, 'SPIKYSHIELD', 'Spiky Shield', 'GRASS', 'Status', 0, 0, 10, 'User', 'ProtectUserFromTargetingMovesSpikyShield', NULL, 4, 0, 'Protects the user from attacks. Also damages attackers that make contact with the user.'),
(330, 'SPORE', 'Spore', 'GRASS', 'Status', 0, 100, 15, 'NearOther', 'SleepTarget', 'CanProtect,CanMirrorMove,Powder', 0, 0, 'The user scatters bursts of spores that induce sleep.'),
(331, 'STRENGTHSAP', 'Strength Sap', 'GRASS', 'Status', 0, 100, 10, 'NearOther', 'HealUserByTargetAttackLowerTargetAttack1', 'CanProtect,CanMirrorMove', 0, 0, 'The user restores its HP by the target''s Attack stat amount. Then lowers the target''s Attack stat.'),
(332, 'STUNSPORE', 'Stun Spore', 'GRASS', 'Status', 0, 75, 30, 'NearOther', 'ParalyzeTarget', 'CanProtect,CanMirrorMove,Powder', 0, 0, 'The user scatters a cloud of paralyzing powder. It may leave the target with paralysis.'),
(333, 'SYNTHESIS', 'Synthesis', 'GRASS', 'Status', 0, 0, 5, 'User', 'HealUserDependingOnWeather', NULL, 0, 0, 'The user restores its own HP. The amount of HP regained varies with the weather.'),
(334, 'WORRYSEED', 'Worry Seed', 'GRASS', 'Status', 0, 100, 10, 'NearOther', 'SetTargetAbilityToInsomnia', 'CanProtect,CanMirrorMove', 0, 0, 'A seed that causes worry is planted on the foe. It prevents sleep by making its Ability Insomnia.'),
(335, 'PRECIPICEBLADES', 'Precipice Blades', 'GROUND', 'Physical', 120, 85, 10, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user attacks its foes by manifesting the power of the land in fearsome blades of stone.'),
(336, 'EARTHQUAKE', 'Earthquake', 'GROUND', 'Physical', 100, 100, 10, 'AllNearOthers', 'DoublePowerIfTargetUnderground', 'CanProtect,CanMirrorMove', 0, 0, 'The user sets off an earthquake that strikes every Pokémon around it.'),
(337, 'HIGHHORSEPOWER', 'High Horsepower', 'GROUND', 'Physical', 95, 95, 10, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user fiercely attacks the target using its entire body.'),
(338, 'EARTHPOWER', 'Earth Power', 'GROUND', 'Special', 90, 100, 10, 'NearOther', 'LowerTargetSpDef1', 'CanProtect,CanMirrorMove', 0, 10, 'The user makes the ground under the foe erupt with power. It may also lower the target''s Sp. Def.'),
(339, 'LANDSWRATH', 'Land''s Wrath', 'GROUND', 'Physical', 90, 100, 10, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove', 0, 0, 'The user gathers the energy of the land and focuses that power on foes to damage them.'),
(340, 'THOUSANDARROWS', 'Thousand Arrows', 'GROUND', 'Physical', 90, 100, 10, 'AllNearFoes', 'HitsTargetInSkyGroundsTarget', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'This move also hits Pokémon that are in the air. Those Pokémon are knocked down to the ground.'),
(341, 'THOUSANDWAVES', 'Thousand Waves', 'GROUND', 'Physical', 90, 100, 10, 'AllNearFoes', 'TrapTargetInBattleMainEffect', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user attacks with a wave that crawls along the ground. Those it hits can''t flee from battle.'),
(342, 'DIG', 'Dig', 'GROUND', 'Physical', 80, 100, 10, 'NearOther', 'TwoTurnAttackInvulnerableUnderground', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user burrows, then attacks on the second turn. It can also be used to exit dungeons.'),
(343, 'DRILLRUN', 'Drill Run', 'GROUND', 'Physical', 80, 95, 10, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'The user crashes into its target while rotating its body like a drill. Critical hits land more easily.'),
(344, 'STOMPINGTANTRUM', 'Stomping Tantrum', 'GROUND', 'Physical', 75, 100, 10, 'NearOther', 'DoublePowerIfUserLastMoveFailed', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user attacks driven by frustration. Power increases if the user''s previous move failed.'),
(345, 'SCORCHINGSANDS', 'Scorching Sands', 'GROUND', 'Special', 70, 100, 10, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove,ThawsUser', 0, 30, 'The user throws scorching sand at the target to attack. This may also burn the target.'),
(346, 'BONECLUB', 'Bone Club', 'GROUND', 'Physical', 65, 85, 20, 'NearOther', 'FlinchTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The user clubs the target with a bone. It may also make the target flinch.'),
(347, 'MUDBOMB', 'Mud Bomb', 'GROUND', 'Special', 65, 85, 10, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove,Bomb', 0, 30, 'The user launches a hard-packed mud ball to attack. It may also lower the target''s accuracy.'),
(348, 'BULLDOZE', 'Bulldoze', 'GROUND', 'Physical', 60, 100, 20, 'AllNearOthers', 'LowerTargetSpeed1WeakerInGrassyTerrain', 'CanProtect,CanMirrorMove', 0, 100, 'The user strikes everything around it by stomping on the ground. It reduces hit Pokémon''s Speed.'),
(349, 'MUDSHOT', 'Mud Shot', 'GROUND', 'Special', 55, 95, 15, 'NearOther', 'LowerTargetSpeed1', 'CanProtect,CanMirrorMove', 0, 100, 'The user attacks by hurling a blob of mud at the target. It also reduces the target''s Speed.'),
(350, 'BONEMERANG', 'Bonemerang', 'GROUND', 'Physical', 50, 90, 10, 'NearOther', 'HitTwoTimes', 'CanProtect,CanMirrorMove', 0, 0, 'The user throws the bone it holds. The bone loops to hit the target twice, coming and going.'),
(351, 'SANDTOMB', 'Sand Tomb', 'GROUND', 'Physical', 35, 85, 15, 'NearOther', 'BindTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user traps the target inside a harshly raging sandstorm for four to five turns.'),
(352, 'BONERUSH', 'Bone Rush', 'GROUND', 'Physical', 25, 90, 10, 'NearOther', 'HitTwoToFiveTimes', 'CanProtect,CanMirrorMove', 0, 0, 'The user strikes the target with a hard bone two to five times in a row.'),
(353, 'MUDSLAP', 'Mud-Slap', 'GROUND', 'Special', 20, 100, 10, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove', 0, 100, 'The user hurls mud in the target''s face to inflict damage and lower its accuracy.'),
(354, 'FISSURE', 'Fissure', 'GROUND', 'Physical', 1, 30, 5, 'NearOther', 'OHKOHitsUndergroundTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user opens up a fissure in the ground and drops the foe in. The target instantly faints if it hits.'),
(355, 'MAGNITUDE', 'Magnitude', 'GROUND', 'Physical', 1, 100, 30, 'AllNearOthers', 'RandomPowerDoublePowerIfTargetUnderground', 'CanProtect,CanMirrorMove', 0, 0, 'The user looses a ground-shaking quake affecting everyone around the user. Its power varies.'),
(356, 'MUDSPORT', 'Mud Sport', 'GROUND', 'Status', 0, 0, 15, 'BothSides', 'StartWeakenElectricMoves', NULL, 0, 0, 'The user covers itself with mud. It weakens Electric-type moves while the user is in the battle.'),
(357, 'ROTOTILLER', 'Rototiller', 'GROUND', 'Status', 0, 0, 10, 'AllBattlers', 'RaiseGroundedGrassBattlersAtkSpAtk1', NULL, 0, 0, 'The user tills the soil to encourage plant growth. This raises the Attack and Sp. Atk of Grass types.'),
(358, 'SANDATTACK', 'Sand Attack', 'GROUND', 'Status', 0, 100, 15, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove', 0, 0, 'Sand is hurled in the target''s face, reducing its accuracy.'),
(359, 'SHOREUP', 'Shore Up', 'GROUND', 'Status', 0, 0, 10, 'User', 'HealUserDependingOnSandstorm', NULL, 0, 0, 'The user regains up to half of its max HP. It restores more HP in a sandstorm.'),
(360, 'SPIKES', 'Spikes', 'GROUND', 'Status', 0, 0, 20, 'FoeSide', 'AddSpikesToFoeSide', NULL, 0, 0, 'The user lays a trap of spikes at the foe''s feet. The trap hurts foes that switch into battle.'),
(361, 'FREEZESHOCK', 'Freeze Shock', 'ICE', 'Physical', 140, 90, 5, 'NearOther', 'TwoTurnAttackParalyzeTarget', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 30, 'On the second turn, the user hits the foe with electrically charged ice. It may also paralyze the foe.'),
(362, 'ICEBURN', 'Ice Burn', 'ICE', 'Special', 140, 90, 5, 'NearOther', 'TwoTurnAttackBurnTarget', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 30, 'On the second turn, an ultracold, freezing wind surrounds the foe. This may leave it with a burn.'),
(363, 'GLACIALLANCE', 'Glacial Lance', 'ICE', 'Physical', 130, 100, 5, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user attacks by hurling a blizzard-cloaked icicle lance at opposing Pokémon.'),
(364, 'BLIZZARD', 'Blizzard', 'ICE', 'Special', 110, 70, 5, 'AllNearFoes', 'FreezeTargetAlwaysHitsInHail', 'CanProtect,CanMirrorMove', 0, 10, 'A howling blizzard is summoned to strike the opposing team. It may also freeze them solid.'),
(365, 'ICEHAMMER', 'Ice Hammer', 'ICE', 'Physical', 100, 90, 10, 'NearOther', 'LowerUserSpeed1', 'Contact,CanProtect,CanMirrorMove,Punching', 0, 0, 'The user swings and hits with its strong, heavy fist. It lowers the user''s Speed, however.'),
(366, 'ICEBEAM', 'Ice Beam', 'ICE', 'Special', 90, 100, 10, 'NearOther', 'FreezeTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The target is struck with an icy-cold beam of energy. It may also freeze the target solid.'),
(367, 'ICICLECRASH', 'Icicle Crash', 'ICE', 'Physical', 85, 90, 10, 'NearOther', 'FlinchTarget', 'CanProtect,CanMirrorMove', 0, 30, 'The user attacks by harshly dropping an icicle onto the foe. It may also make the target flinch.'),
(368, 'ICEPUNCH', 'Ice Punch', 'ICE', 'Physical', 75, 100, 15, 'NearOther', 'FreezeTarget', 'Contact,CanProtect,CanMirrorMove,Punching', 0, 10, 'The target is punched with an icy fist. It may also leave the target frozen.'),
(369, 'FREEZEDRY', 'Freeze-Dry', 'ICE', 'Special', 70, 100, 20, 'NearOther', 'FreezeTargetSuperEffectiveAgainstWater', 'CanProtect,CanMirrorMove', 0, 10, 'The user rapidly cools the target. This may freeze the target. Is super-effective on Water types.'),
(370, 'AURORABEAM', 'Aurora Beam', 'ICE', 'Special', 65, 100, 20, 'NearOther', 'LowerTargetAttack1', 'CanProtect,CanMirrorMove', 0, 10, 'The target is hit with a rainbow-colored beam. This may also lower the target''s Attack stat.'),
(371, 'GLACIATE', 'Glaciate', 'ICE', 'Special', 65, 95, 10, 'AllNearFoes', 'LowerTargetSpeed1', 'CanProtect,CanMirrorMove', 0, 100, 'The user attacks by blowing freezing cold air at the foe. This attack reduces the targets'' Speed stat.'),
(372, 'ICEFANG', 'Ice Fang', 'ICE', 'Physical', 65, 95, 15, 'NearOther', 'FreezeFlinchTarget', 'Contact,CanProtect,CanMirrorMove,Biting', 0, 101, 'The user bites with cold-infused fangs. It may also make the target flinch or leave it frozen.'),
(373, 'AVALANCHE', 'Avalanche', 'ICE', 'Physical', 60, 100, 10, 'NearOther', 'DoublePowerIfUserLostHPThisTurn', 'Contact,CanProtect,CanMirrorMove', -4, 0, 'An attack move that inflicts double the damage if the user has been hurt by the foe in the same turn.'),
(374, 'FROSTBREATH', 'Frost Breath', 'ICE', 'Special', 60, 90, 10, 'NearOther', 'AlwaysCriticalHit', 'CanProtect,CanMirrorMove', 0, 0, 'The user blows a cold breath on the target. This attack always results in a critical hit.'),
(375, 'ICYWIND', 'Icy Wind', 'ICE', 'Special', 55, 95, 15, 'AllNearFoes', 'LowerTargetSpeed1', 'CanProtect,CanMirrorMove', 0, 100, 'The user attacks with a gust of chilled air. It also lowers the targets'' Speed stat.'),
(376, 'ICESHARD', 'Ice Shard', 'ICE', 'Physical', 40, 100, 30, 'NearOther', 'None', 'CanProtect,CanMirrorMove', 1, 0, 'The user flash freezes chunks of ice and hurls them at the target. This move always goes first.'),
(377, 'POWDERSNOW', 'Powder Snow', 'ICE', 'Special', 40, 100, 25, 'AllNearFoes', 'FreezeTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The user attacks with a chilling gust of powdery snow. It may also freeze the targets.'),
(378, 'ICEBALL', 'Ice Ball', 'ICE', 'Physical', 30, 90, 20, 'NearOther', 'MultiTurnAttackPowersUpEachTurn', 'Contact,CanProtect,CanMirrorMove,Bomb', 0, 0, 'The user continually rolls into the target over five turns. It becomes stronger each time it hits.'),
(379, 'ICICLESPEAR', 'Icicle Spear', 'ICE', 'Physical', 25, 100, 30, 'NearOther', 'HitTwoToFiveTimes', 'CanProtect,CanMirrorMove', 0, 0, 'The user launches sharp icicles at the target. It strikes two to five times in a row.'),
(380, 'TRIPLEAXEL', 'Triple Axel', 'ICE', 'Physical', 20, 90, 10, 'NearOther', 'HitThreeTimesPowersUpWithEachHit', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A consecutive three-kick attack that becomes more powerful with each successful hit.'),
(381, 'SHEERCOLD', 'Sheer Cold', 'ICE', 'Special', 1, 30, 5, 'NearOther', 'OHKOIce', 'CanProtect,CanMirrorMove', 0, 0, 'The foe is attacked with a blast of absolute-zero cold. The target instantly faints if it hits.'),
(382, 'AURORAVEIL', 'Aurora Veil', 'ICE', 'Status', 0, 0, 20, 'UserSide', 'StartWeakenDamageAgainstUserSideIfHail', NULL, 0, 0, 'This move reduces damage from attacks for five turns. This can be used only in a hailstorm.'),
(383, 'HAIL', 'Hail', 'ICE', 'Status', 0, 0, 10, 'BothSides', 'StartHailWeather', NULL, 0, 0, 'The user summons a hail storm lasting five turns. It damages all Pokémon except the Ice type.'),
(384, 'HAZE', 'Haze', 'ICE', 'Status', 0, 0, 30, 'BothSides', 'ResetAllBattlersStatStages', NULL, 0, 0, 'The user creates a haze that eliminates every stat change among all the Pokémon engaged in battle.'),
(385, 'MIST', 'Mist', 'ICE', 'Status', 0, 0, 30, 'UserSide', 'StartUserSideImmunityToStatStageLowering', NULL, 0, 0, 'The user cloaks its body with a white mist that prevents any of its stats from being cut for five turns.'),
(386, 'EXPLOSION', 'Explosion', 'NORMAL', 'Physical', 250, 100, 5, 'AllNearOthers', 'UserFaintsExplosive', 'CanProtect,CanMirrorMove', 0, 0, 'The user explodes to inflict damage on those around it. The user faints upon using this move.'),
(387, 'SELFDESTRUCT', 'Self-Destruct', 'NORMAL', 'Physical', 200, 100, 5, 'AllNearOthers', 'UserFaintsExplosive', 'CanProtect,CanMirrorMove', 0, 0, 'The user blows up to inflict damage on all Pokémon in battle. The user faints upon using this move.'),
(388, 'GIGAIMPACT', 'Giga Impact', 'NORMAL', 'Physical', 150, 90, 5, 'NearOther', 'AttackAndSkipNextTurn', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user charges at the target using every bit of its power. The user must rest on the next turn.'),
(389, 'HYPERBEAM', 'Hyper Beam', 'NORMAL', 'Special', 150, 90, 5, 'NearOther', 'AttackAndSkipNextTurn', 'CanProtect,CanMirrorMove', 0, 0, 'The foe is attacked with a powerful beam. The user must rest on the next turn to regain its energy.'),
(390, 'BOOMBURST', 'Boomburst', 'NORMAL', 'Special', 140, 100, 10, 'AllNearOthers', 'None', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user attacks everything around it with the destructive power of a terrible, explosive sound.'),
(391, 'LASTRESORT', 'Last Resort', 'NORMAL', 'Physical', 140, 100, 5, 'NearOther', 'FailsIfUserHasUnusedMove', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'This move can be used only after the user has used all the other moves it knows in the battle.'),
(392, 'SKULLBASH', 'Skull Bash', 'NORMAL', 'Physical', 130, 100, 10, 'NearOther', 'TwoTurnAttackChargeRaiseUserDefense1', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user tucks in its head to raise its Defense in the first turn, then rams the foe on the next turn.'),
(393, 'DOUBLEEDGE', 'Double-Edge', 'NORMAL', 'Physical', 120, 100, 15, 'NearOther', 'RecoilThirdOfDamageDealt', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A reckless, life-risking tackle. It also damages the user by a fairly large amount, however.'),
(394, 'HEADCHARGE', 'Head Charge', 'NORMAL', 'Physical', 120, 100, 15, 'NearOther', 'RecoilQuarterOfDamageDealt', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user charges its head into the foe, using its powerful guard hair. The user also takes damage.'),
(395, 'MEGAKICK', 'Mega Kick', 'NORMAL', 'Physical', 120, 75, 5, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is attacked by a kick launched with muscle-packed power.'),
(396, 'MULTIATTACK', 'Multi-Attack', 'NORMAL', 'Physical', 120, 100, 10, 'NearOther', 'TypeDependsOnUserMemory', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Cloaking itself in high energy, the user slams into the target. This move''s type depends on the held memory.'),
(397, 'TECHNOBLAST', 'Techno Blast', 'NORMAL', 'Special', 120, 100, 5, 'NearOther', 'TypeDependsOnUserDrive', 'CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'The user fires a beam of light at its target. The type changes depending on the Drive the user holds.'),
(398, 'THRASH', 'Thrash', 'NORMAL', 'Physical', 120, 100, 10, 'RandomNearFoe', 'MultiTurnAttackConfuseUserAtEnd', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user rampages and attacks for two to three turns. It then becomes confused, however.'),
(399, 'EGGBOMB', 'Egg Bomb', 'NORMAL', 'Physical', 100, 75, 10, 'NearOther', 'None', 'CanProtect,CanMirrorMove,Bomb', 0, 0, 'A large egg is hurled at the target with maximum force to inflict damage.'),
(400, 'JUDGMENT', 'Judgment', 'NORMAL', 'Special', 100, 100, 10, 'NearOther', 'TypeDependsOnUserPlate', 'CanProtect,CanMirrorMove', 0, 0, 'The user releases countless shots of light. Its type varies with the kind of Plate the user is holding.');
REPLACE INTO `battlemon_moves` (`id`, `internal_name`, `name`, `type`, `move_category`, `power`, `accuracy`, `pp`, `target`, `function_code`, `flags`, `priority`, `effect_chance`, `description`) VALUES
(401, 'HYPERVOICE', 'Hyper Voice', 'NORMAL', 'Special', 90, 100, 10, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user lets loose a horribly echoing shout with the power to inflict damage.'),
(402, 'REVELATIONDANCE', 'Revelation Dance', 'NORMAL', 'Special', 90, 100, 15, 'NearOther', 'TypeIsUserFirstType', 'CanProtect,CanMirrorMove,Dance', 0, 0, 'The user attacks the target by dancing very hard. The user''s type determines the type of this move.'),
(403, 'ROCKCLIMB', 'Rock Climb', 'NORMAL', 'Physical', 90, 85, 20, 'NearOther', 'ConfuseTarget', 'Contact,CanProtect,CanMirrorMove', 0, 20, 'The user attacks the target by smashing into it with incredible force. It may also confuse the target.'),
(404, 'TAKEDOWN', 'Take Down', 'NORMAL', 'Physical', 90, 85, 20, 'NearOther', 'RecoilQuarterOfDamageDealt', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A reckless, full-body charge attack for slamming into the foe. It also damages the user a little.'),
(405, 'UPROAR', 'Uproar', 'NORMAL', 'Special', 90, 100, 10, 'RandomNearFoe', 'MultiTurnAttackPreventSleeping', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user attacks in an uproar for three turns. Over that time, no one can fall asleep.'),
(406, 'BODYSLAM', 'Body Slam', 'NORMAL', 'Physical', 85, 100, 15, 'NearOther', 'ParalyzeTarget', 'Contact,CanProtect,CanMirrorMove,TramplesMinimize', 0, 30, 'The user drops onto the target with its full body weight. It may leave the target with paralysis.'),
(407, 'EXTREMESPEED', 'Extreme Speed', 'NORMAL', 'Physical', 80, 100, 5, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 2, 0, 'The user charges the target at blinding speed. This attack always goes before any other move.'),
(408, 'HYPERFANG', 'Hyper Fang', 'NORMAL', 'Physical', 80, 90, 15, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove,Biting', 0, 10, 'The user bites hard on the target with its sharp front fangs. It may also make the target flinch.'),
(409, 'MEGAPUNCH', 'Mega Punch', 'NORMAL', 'Physical', 80, 85, 20, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove,Punching', 0, 0, 'The target is slugged by a punch thrown with muscle-packed power.'),
(410, 'RAZORWIND', 'Razor Wind', 'NORMAL', 'Special', 80, 100, 10, 'AllNearFoes', 'TwoTurnAttack', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'A two-turn attack. Blades of wind hit the foe on the second turn. Critical hits land more easily.'),
(411, 'SLAM', 'Slam', 'NORMAL', 'Physical', 80, 75, 20, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is slammed with a long tail, vines, etc., to inflict damage.'),
(412, 'STRENGTH', 'Strength', 'NORMAL', 'Physical', 80, 100, 15, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is slugged with a punch thrown at maximum power. It can also be used to move heavy boulders.'),
(413, 'TRIATTACK', 'Tri Attack', 'NORMAL', 'Special', 80, 100, 10, 'NearOther', 'ParalyzeBurnOrFreezeTarget', 'CanProtect,CanMirrorMove', 0, 20, 'The user strikes with a simultaneous three-beam attack. May also paralyze, burn, or freeze the target.'),
(414, 'CRUSHCLAW', 'Crush Claw', 'NORMAL', 'Physical', 75, 95, 10, 'NearOther', 'LowerTargetDefense1', 'Contact,CanProtect,CanMirrorMove', 0, 50, 'The user slashes the target with hard and sharp claws. It may also lower the target''s Defense.'),
(415, 'RELICSONG', 'Relic Song', 'NORMAL', 'Special', 75, 100, 10, 'AllNearFoes', 'SleepTargetChangeUserMeloettaForm', 'CanProtect,CanMirrorMove,Sound,CannotMetronome', 0, 10, 'An ancient song appeals to the hearts of those listening. It may also induce sleep.'),
(416, 'CHIPAWAY', 'Chip Away', 'NORMAL', 'Physical', 70, 100, 20, 'NearOther', 'IgnoreTargetDefSpDefEvaStatStages', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Seeking an opening, the user strikes continually. The foe''s stat changes don''t affect the damage.'),
(417, 'DIZZYPUNCH', 'Dizzy Punch', 'NORMAL', 'Physical', 70, 100, 10, 'NearOther', 'ConfuseTarget', 'Contact,CanProtect,CanMirrorMove,Punching', 0, 20, 'The target is hit with rhythmically launched punches that may also leave it confused.'),
(418, 'FACADE', 'Facade', 'NORMAL', 'Physical', 70, 100, 20, 'NearOther', 'DoublePowerIfUserPoisonedBurnedParalyzed', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'An attack move that doubles its power if the user is poisoned, burned, or has paralysis.'),
(419, 'HEADBUTT', 'Headbutt', 'NORMAL', 'Physical', 70, 100, 15, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove', 0, 30, 'The user sticks out its head and attacks by charging into the foe. It may also make the target flinch.'),
(420, 'RETALIATE', 'Retaliate', 'NORMAL', 'Physical', 70, 100, 5, 'NearOther', 'DoublePowerIfAllyFaintedLastTurn', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Gets revenge for a fainted ally. If an ally fainted in the last turn, this attack''s damage increases.'),
(421, 'SECRETPOWER', 'Secret Power', 'NORMAL', 'Physical', 70, 100, 20, 'NearOther', 'EffectDependsOnEnvironment', 'CanProtect,CanMirrorMove', 0, 30, 'The user attacks with a secret power. Its added effects vary depending on the user''s environment.'),
(422, 'SLASH', 'Slash', 'NORMAL', 'Physical', 70, 100, 20, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'The target is attacked with a slash of claws or blades. Critical hits land more easily.'),
(423, 'SMELLINGSALTS', 'Smelling Salts', 'NORMAL', 'Physical', 70, 100, 10, 'NearOther', 'DoublePowerIfTargetParalyzedCureTarget', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'This attack inflicts double damage on a paralyzed foe. It also cures the target''s paralysis, however.'),
(424, 'HORNATTACK', 'Horn Attack', 'NORMAL', 'Physical', 65, 100, 25, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is jabbed with a sharply pointed horn to inflict damage.'),
(425, 'STOMP', 'Stomp', 'NORMAL', 'Physical', 65, 100, 20, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove,TramplesMinimize', 0, 30, 'The target is stomped with a big foot. It may also make the target flinch.'),
(426, 'COVET', 'Covet', 'NORMAL', 'Physical', 60, 100, 25, 'NearOther', 'UserTakesTargetItem', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user endearingly approaches the target, then steals the target''s held item.'),
(427, 'HIDDENPOWER', 'Hidden Power', 'NORMAL', 'Special', 60, 100, 15, 'NearOther', 'TypeDependsOnUserIVs', 'CanProtect,CanMirrorMove', 0, 0, 'A unique attack that varies in type and intensity depending on the Pokémon using it.'),
(428, 'ROUND', 'Round', 'NORMAL', 'Special', 60, 100, 15, 'NearOther', 'UsedAfterAllyRoundWithDoublePower', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user attacks with a song. Others can join in the Round and make the attack do greater damage.'),
(429, 'SWIFT', 'Swift', 'NORMAL', 'Special', 60, 0, 20, 'AllNearFoes', 'None', 'CanProtect,CanMirrorMove', 0, 0, 'Star-shaped rays are shot at the opposing team. This attack never misses.'),
(430, 'VISEGRIP', 'Vise Grip', 'NORMAL', 'Physical', 55, 100, 30, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is gripped and squeezed from both sides to inflict damage.'),
(431, 'CUT', 'Cut', 'NORMAL', 'Physical', 50, 95, 30, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is cut with a scythe or a claw. It can also be used to cut down thin trees.'),
(432, 'RAPIDSPIN', 'Rapid Spin', 'NORMAL', 'Physical', 50, 100, 40, 'NearOther', 'RemoveUserBindingAndEntryHazards', 'Contact,CanProtect,CanMirrorMove', 0, 100, 'A spin attack that raises the user''s Speed and eliminates the effects of Bind, Spikes, etc.'),
(433, 'SNORE', 'Snore', 'NORMAL', 'Special', 50, 100, 15, 'NearOther', 'FlinchTargetFailsIfUserNotAsleep', 'CanProtect,CanMirrorMove,Sound', 0, 30, 'An attack that can be used only if the user is asleep. The harsh noise may also make the target flinch.'),
(434, 'TERRAINPULSE', 'Terrain Pulse', 'NORMAL', 'Special', 50, 100, 10, 'NearOther', 'TypeAndPowerDependOnTerrain', 'CanProtect,CanMirrorMove,Pulse', 0, 0, 'Utilizes the power of the terrain to attack. This move''s type and power vary with the terrain.'),
(435, 'WEATHERBALL', 'Weather Ball', 'NORMAL', 'Special', 50, 100, 10, 'NearOther', 'TypeAndPowerDependOnWeather', 'CanProtect,CanMirrorMove,Bomb', 0, 0, 'An attack move that varies in power and type depending on the weather.'),
(436, 'ECHOEDVOICE', 'Echoed Voice', 'NORMAL', 'Special', 40, 100, 15, 'NearOther', 'PowerHigherWithConsecutiveUseOnUserSide', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user attacks the foe with an echoing voice. If this move is used every turn, it does greater damage.'),
