(439, 'HOLDBACK', 'Hold Back', 'NORMAL', 'Physical', 40, 100, 40, 'NearOther', 'CannotMakeTargetFaint', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user holds back when it attacks, and the target is left with at least 1 HP.'),
(440, 'PAYDAY', 'Pay Day', 'NORMAL', 'Physical', 40, 100, 20, 'NearOther', 'AddMoneyGainedFromBattle', 'CanProtect,CanMirrorMove', 0, 0, 'Numerous coins are hurled at the target to inflict damage. Money is earned after battle.'),
(441, 'POUND', 'Pound', 'NORMAL', 'Physical', 40, 100, 35, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is physically pounded with a long tail or a foreleg, etc.'),
