(446, 'FEINT', 'Feint', 'NORMAL', 'Physical', 30, 100, 10, 'NearOther', 'RemoveProtections', 'CanMirrorMove', 2, 0, 'An attack that hits a target using Protect or Detect. It also lifts the effects of those moves.'),
(447, 'TAILSLAP', 'Tail Slap', 'NORMAL', 'Physical', 25, 85, 10, 'NearOther', 'HitTwoToFiveTimes', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user attacks by striking the target with its hard tail. It hits the Pokémon two to five times in a row.'),
(448, 'RAGE', 'Rage', 'NORMAL', 'Physical', 20, 100, 20, 'NearOther', 'StartRaiseUserAtk1WhenDamaged', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'As long as this move is in use, the user''s Attack rises each time the user is hit in battle.'),
