(450, 'COMETPUNCH', 'Comet Punch', 'NORMAL', 'Physical', 18, 85, 15, 'NearOther', 'HitTwoToFiveTimes', 'Contact,CanProtect,CanMirrorMove,Punching', 0, 0, 'The target is hit with a flurry of punches that strike two to five times in a row.'),
(451, 'FURYSWIPES', 'Fury Swipes', 'NORMAL', 'Physical', 18, 80, 15, 'NearOther', 'HitTwoToFiveTimes', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is raked with sharp claws or scythes for two to five times in quick succession.'),
