(453, 'BIND', 'Bind', 'NORMAL', 'Physical', 15, 85, 20, 'NearOther', 'BindTarget', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'Things such as long bodies or tentacles are used to bind and squeeze the foe for four to five turns.'),
(454, 'DOUBLESLAP', 'Double Slap', 'NORMAL', 'Physical', 15, 85, 10, 'NearOther', 'HitTwoToFiveTimes', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is slapped repeatedly, back and forth, two to five times in a row.'),
(455, 'FURYATTACK', 'Fury Attack', 'NORMAL', 'Physical', 15, 85, 20, 'NearOther', 'HitTwoToFiveTimes', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is jabbed repeatedly with a horn or beak two to five times in a row.'),
(456, 'WRAP', 'Wrap', 'NORMAL', 'Physical', 15, 90, 20, 'NearOther', 'BindTarget', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A long body or vines are used to wrap and squeeze the target for four to five turns.'),
(457, 'CONSTRICT', 'Constrict', 'NORMAL', 'Physical', 10, 100, 35, 'NearOther', 'LowerTargetSpeed1', 'Contact,CanProtect,CanMirrorMove', 0, 10, 'The foe is attacked with long, creeping tentacles or vines. It may also lower the target''s Speed.'),
(458, 'BIDE', 'Bide', 'NORMAL', 'Physical', 1, 0, 10, 'None', 'MultiTurnAttackBideThenReturnDoubleDamage', 'Contact,CanProtect', 1, 0, 'The user endures attacks for two turns, then strikes back to cause double the damage taken.'),
