(463, 'GUILLOTINE', 'Guillotine', 'NORMAL', 'Physical', 1, 30, 5, 'NearOther', 'OHKO', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A vicious, tearing attack with big pincers. The target will faint instantly if this attack hits.'),
(464, 'HORNDRILL', 'Horn Drill', 'NORMAL', 'Physical', 1, 30, 5, 'NearOther', 'OHKO', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user stabs the foe with a horn that rotates like a drill. If it hits, the target faints instantly.'),
(465, 'NATURALGIFT', 'Natural Gift', 'NORMAL', 'Physical', 1, 100, 15, 'NearOther', 'TypeAndPowerDependOnUserBerry', 'CanProtect,CanMirrorMove', 0, 0, 'The user draws power to attack by using its held Berry. The Berry determines its type and power.'),
(466, 'PRESENT', 'Present', 'NORMAL', 'Physical', 1, 90, 15, 'NearOther', 'RandomlyDamageOrHealTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks by giving the target a gift with a hidden trap. It restores HP sometimes, however.'),
(467, 'RETURN', 'Return', 'NORMAL', 'Physical', 1, 100, 20, 'NearOther', 'PowerHigherWithUserHappiness', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'A full-power attack that grows more powerful the more the user likes its Trainer.'),
(468, 'SONICBOOM', 'Sonic Boom', 'NORMAL', 'Special', 1, 90, 20, 'NearOther', 'FixedDamage20', 'CanProtect,CanMirrorMove', 0, 0, 'The target is hit with a destructive shock wave that always inflicts 20 HP damage.'),
(469, 'SPITUP', 'Spit Up', 'NORMAL', 'Special', 1, 100, 10, 'NearOther', 'PowerDependsOnUserStockpile', 'CanProtect', 0, 0, 'The power stored using the move Stockpile is released all at once in an attack.'),
(470, 'SUPERFANG', 'Super Fang', 'NORMAL', 'Physical', 1, 90, 10, 'NearOther', 'FixedDamageHalfTargetHP', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user chomps hard on the target with its sharp front fangs. It cuts the target''s HP to half.'),
(471, 'TRUMPCARD', 'Trump Card', 'NORMAL', 'Special', 1, 0, 5, 'NearOther', 'PowerHigherWithLessPP', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The fewer PP this move has, the greater its attack power.'),
(472, 'WRINGOUT', 'Wring Out', 'NORMAL', 'Special', 1, 100, 5, 'NearOther', 'PowerHigherWithTargetHP', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The user powerfully wrings the foe. The more HP the foe has, the greater this attack''s power.'),
(473, 'ACUPRESSURE', 'Acupressure', 'NORMAL', 'Status', 0, 0, 30, 'UserOrNearAlly', 'RaiseTargetRandomStat2', NULL, 0, 0, 'The user applies pressure to stress points, sharply boosting one of its stats.'),
(474, 'AFTERYOU', 'After You', 'NORMAL', 'Status', 0, 0, 15, 'NearOther', 'TargetActsNext', NULL, 0, 0, 'The user helps the target and makes it use its move right after the user.'),
(475, 'ASSIST', 'Assist', 'NORMAL', 'Status', 0, 0, 20, 'User', 'UseRandomMoveFromUserParty', NULL, 0, 0, 'The user hurriedly and randomly uses a move among those known by other Pokémon in the party.'),
(476, 'ATTRACT', 'Attract', 'NORMAL', 'Status', 0, 100, 15, 'NearOther', 'AttractTarget', 'CanProtect,CanMirrorMove', 0, 0, 'If it is the opposite gender of the user, the target becomes infatuated and less likely to attack.'),
(477, 'BATONPASS', 'Baton Pass', 'NORMAL', 'Status', 0, 0, 40, 'User', 'SwitchOutUserPassOnEffects', NULL, 0, 0, 'The user switches places with a party Pokémon in waiting, passing along any stat changes.'),
(478, 'BELLYDRUM', 'Belly Drum', 'NORMAL', 'Status', 0, 0, 10, 'User', 'MaxUserAttackLoseHalfOfTotalHP', NULL, 0, 0, 'The user maximizes its Attack stat in exchange for HP equal to half its max HP.'),
(479, 'BESTOW', 'Bestow', 'NORMAL', 'Status', 0, 0, 15, 'NearOther', 'TargetTakesUserItem', 'CanMirrorMove', 0, 0, 'The user passes its held item to the target when the target isn''t holding an item.'),
(480, 'BLOCK', 'Block', 'NORMAL', 'Status', 0, 0, 5, 'NearOther', 'TrapTargetInBattle', 'CanMirrorMove', 0, 0, 'The user blocks the target''s way with arms spread wide to prevent escape.');
