(483, 'CELEBRATE', 'Celebrate', 'NORMAL', 'Status', 0, 0, 40, 'User', 'DoesNothingCongratulations', NULL, 0, 0, 'The Pokémon congratulates you on your special day!'),
(484, 'CONFIDE', 'Confide', 'NORMAL', 'Status', 0, 0, 20, 'NearOther', 'LowerTargetSpAtk1', 'CanMirrorMove,Sound', 0, 0, 'The user tells the target a secret. The target loses focus and its Sp. Atk stat is lowered.'),
(485, 'CONVERSION', 'Conversion', 'NORMAL', 'Status', 0, 0, 30, 'User', 'SetUserTypesToUserMoveType', NULL, 0, 0, 'The user changes its type to become the same type as one of its moves.'),
(486, 'CONVERSION2', 'Conversion 2', 'NORMAL', 'Status', 0, 0, 30, 'NearOther', 'SetUserTypesToResistLastAttack', NULL, 0, 0, 'The user changes its type to make itself resistant to the type of the attack the opponent used last.'),
(487, 'COPYCAT', 'Copycat', 'NORMAL', 'Status', 0, 0, 20, 'User', 'UseLastMoveUsed', NULL, 0, 0, 'The user mimics the move used immediately before it. The move fails if no other move has been used yet.'),
(488, 'COURTCHANGE', 'Court Change', 'NORMAL', 'Status', 0, 0, 10, 'BothSides', 'SwapSideEffects', 'CanMirrorMove', 0, 0, 'With its mysterious power, the user swaps the effects on either side of the field.'),
(489, 'DEFENSECURL', 'Defense Curl', 'NORMAL', 'Status', 0, 0, 40, 'User', 'RaiseUserDefense1CurlUpUser', NULL, 0, 0, 'The user curls up to conceal weak spots and raise its Defense stat.'),
(490, 'DISABLE', 'Disable', 'NORMAL', 'Status', 0, 100, 20, 'NearOther', 'DisableTargetLastMoveUsed', 'CanProtect,CanMirrorMove', 0, 0, 'For four turns, this move prevents the target from using the move it last used.'),
(491, 'DOUBLETEAM', 'Double Team', 'NORMAL', 'Status', 0, 0, 15, 'User', 'RaiseUserEvasion1', NULL, 0, 0, 'By moving rapidly, the user makes illusory copies of itself to raise its evasiveness.'),
(492, 'ENCORE', 'Encore', 'NORMAL', 'Status', 0, 100, 5, 'NearOther', 'DisableTargetUsingDifferentMove', 'CanProtect,CanMirrorMove', 0, 0, 'The user compels the target to keep using only the move it last used for three turns.'),
(493, 'ENDURE', 'Endure', 'NORMAL', 'Status', 0, 0, 10, 'User', 'UserEnduresFaintingThisTurn', NULL, 4, 0, 'The user endures any attack with at least 1 HP. Its chance of failing rises if it is used in succession.'),
(494, 'ENTRAINMENT', 'Entrainment', 'NORMAL', 'Status', 0, 100, 15, 'NearOther', 'SetTargetAbilityToUserAbility', 'CanProtect,CanMirrorMove', 0, 0, 'The user dances to compel the target to mimic it, making the target''s Ability the same as the user''s.'),
(495, 'FLASH', 'Flash', 'NORMAL', 'Status', 0, 100, 20, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove', 0, 0, 'The user flashes a light that cuts the target''s accuracy. It can also be used to illuminate caves.'),
(496, 'FOCUSENERGY', 'Focus Energy', 'NORMAL', 'Status', 0, 0, 30, 'User', 'RaiseUserCriticalHitRate2', NULL, 0, 0, 'The user takes a deep breath and focuses so that critical hits land more easily.'),
(497, 'FOLLOWME', 'Follow Me', 'NORMAL', 'Status', 0, 0, 20, 'User', 'RedirectAllMovesToUser', NULL, 2, 0, 'The user draws attention to itself, making all targets take aim only at the user.'),
(498, 'FORESIGHT', 'Foresight', 'NORMAL', 'Status', 0, 0, 40, 'NearOther', 'StartNegateTargetEvasionStatStageAndGhostImmunity', 'CanProtect,CanMirrorMove', 0, 0, 'Enables the user to hit a Ghost type with any kind of move. It also enables the user to hit an evasive foe.'),
(499, 'GLARE', 'Glare', 'NORMAL', 'Status', 0, 100, 30, 'NearOther', 'ParalyzeTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user intimidates the target with the pattern on its belly to cause paralysis.'),
(500, 'GROWL', 'Growl', 'NORMAL', 'Status', 0, 100, 40, 'AllNearFoes', 'LowerTargetAttack1', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'The user growls in an endearing way, making the foe less wary. The foe''s Attack stat is lowered.'),
(501, 'GROWTH', 'Growth', 'NORMAL', 'Status', 0, 0, 20, 'User', 'RaiseUserAtkSpAtk1Or2InSun', NULL, 0, 0, 'The user''s body grows all at once, raising the Atk and Sp. Atk stats.'),
(502, 'HAPPYHOUR', 'Happy Hour', 'NORMAL', 'Status', 0, 0, 30, 'UserSide', 'DoubleMoneyGainedFromBattle', NULL, 0, 0, 'Using Happy Hour doubles the amount of prize money received after battle.'),
(503, 'HARDEN', 'Harden', 'NORMAL', 'Status', 0, 0, 30, 'User', 'RaiseUserDefense1', NULL, 0, 0, 'The user stiffens all the muscles in its body to raise its Defense stat.'),
(504, 'HEALBELL', 'Heal Bell', 'NORMAL', 'Status', 0, 0, 5, 'UserAndAllies', 'CureUserPartyStatus', 'Sound', 0, 0, 'The user makes a soothing bell chime to heal the status problems of all the party Pokémon.'),
(505, 'HELPINGHAND', 'Helping Hand', 'NORMAL', 'Status', 0, 0, 20, 'NearAlly', 'PowerUpAllyMove', NULL, 5, 0, 'The user assists an ally by boosting the power of its attack.'),
(506, 'HOLDHANDS', 'Hold Hands', 'NORMAL', 'Status', 0, 0, 40, 'NearAlly', 'DoesNothingFailsIfNoAlly', NULL, 0, 0, 'The user and an ally hold hands. This makes them very happy.'),
(507, 'HOWL', 'Howl', 'NORMAL', 'Status', 0, 0, 40, 'UserAndAllies', 'RaiseTargetAttack1', 'Sound', 0, 0, 'The user howls loudly to raise the spirit of itself and allies, boosting their Attack stats.'),
(508, 'LASERFOCUS', 'Laser Focus', 'NORMAL', 'Status', 0, 0, 30, 'User', 'EnsureNextCriticalHit', NULL, 0, 0, 'The user focuses intensely. The attack on the next turn always results in a critical hit.'),
(509, 'LEER', 'Leer', 'NORMAL', 'Status', 0, 100, 30, 'AllNearFoes', 'LowerTargetDefense1', 'CanProtect,CanMirrorMove', 0, 0, 'The user gains an intimidating leer with sharp eyes. The target''s Defense stat is reduced.'),
(510, 'LOCKON', 'Lock-On', 'NORMAL', 'Status', 0, 0, 5, 'NearOther', 'EnsureNextMoveAlwaysHits', 'CanProtect,CanMirrorMove', 0, 0, 'The user takes sure aim at the target. It ensures the next attack does not fail to hit the target.'),
(511, 'LOVELYKISS', 'Lovely Kiss', 'NORMAL', 'Status', 0, 75, 10, 'NearOther', 'SleepTarget', 'CanProtect,CanMirrorMove', 0, 0, 'With a scary face, the user tries to force a kiss on the target. If it suceeds, the target falls asleep.'),
(512, 'LUCKYCHANT', 'Lucky Chant', 'NORMAL', 'Status', 0, 0, 30, 'UserSide', 'StartPreventCriticalHitsAgainstUserSide', NULL, 0, 0, 'The user chants an incantation toward the sky, preventing the foe from landing critical hits.'),
(513, 'MEFIRST', 'Me First', 'NORMAL', 'Status', 0, 0, 20, 'NearFoe', 'UseMoveTargetIsAboutToUse', 'CanProtect', 0, 0, 'The user tries to cut ahead of the foe to steal and use the foe''s intended move with greater power.'),
(514, 'MEANLOOK', 'Mean Look', 'NORMAL', 'Status', 0, 0, 5, 'NearOther', 'TrapTargetInBattle', 'CanMirrorMove', 0, 0, 'The user pins the target with a dark, arresting look. The target becomes unable to flee.'),
