(519, 'MINIMIZE', 'Minimize', 'NORMAL', 'Status', 0, 0, 10, 'User', 'RaiseUserEvasion2MinimizeUser', NULL, 0, 0, 'The user compresses its body to make itself look smaller, which sharply raises its evasiveness.'),
(520, 'MORNINGSUN', 'Morning Sun', 'NORMAL', 'Status', 0, 0, 5, 'User', 'HealUserDependingOnWeather', NULL, 0, 0, 'The user restores its own HP. The amount of HP regained varies with the weather.'),
(521, 'NATUREPOWER', 'Nature Power', 'NORMAL', 'Status', 0, 0, 20, 'NearOther', 'UseMoveDependingOnEnvironment', NULL, 0, 0, 'An attack that makes use of nature''s power. Its effects vary depending on the user''s environment.'),
(522, 'NOBLEROAR', 'Noble Roar', 'NORMAL', 'Status', 0, 0, 30, 'NearOther', 'LowerTargetAtkSpAtk1', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'Letting out a noble roar, the user intimidates the target and lowers its Attack and Sp. Atk.'),
