(526, 'PLAYNICE', 'Play Nice', 'NORMAL', 'Status', 0, 0, 20, 'NearOther', 'LowerTargetAttack1BypassSubstitute', 'CanMirrorMove', 0, 0, 'The user and target become friends. The target loses its will to fight, lowering its Attack stat.'),
(527, 'PROTECT', 'Protect', 'NORMAL', 'Status', 0, 0, 10, 'User', 'ProtectUser', NULL, 4, 0, 'It enables the user to evade all attacks. Its chance of failing rises if it is used in succession.'),
(528, 'PSYCHUP', 'Psych Up', 'NORMAL', 'Status', 0, 0, 10, 'NearOther', 'UserCopyTargetStatStages', NULL, 0, 0, 'The user hypnotizes itself into copying any stat change made by the target.'),
(529, 'RECOVER', 'Recover', 'NORMAL', 'Status', 0, 0, 10, 'User', 'HealUserHalfOfTotalHP', NULL, 0, 0, 'Restoring its own cells, the user restores its own HP by half of its max HP.'),
(530, 'RECYCLE', 'Recycle', 'NORMAL', 'Status', 0, 0, 10, 'User', 'RestoreUserConsumedItem', NULL, 0, 0, 'The user recycles a held item that has been used in battle so it can be used again.'),
