(535, 'SCARYFACE', 'Scary Face', 'NORMAL', 'Status', 0, 100, 10, 'NearOther', 'LowerTargetSpeed2', 'CanProtect,CanMirrorMove', 0, 0, 'The user frightens the target with a scary face to harshly reduce its Speed stat.'),
(536, 'SCREECH', 'Screech', 'NORMAL', 'Status', 0, 85, 40, 'NearOther', 'LowerTargetDefense2', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'An earsplitting screech harshly reduces the target''s Defense stat.'),
(537, 'SHARPEN', 'Sharpen', 'NORMAL', 'Status', 0, 0, 30, 'User', 'RaiseUserAttack1', NULL, 0, 0, 'The user reduces its polygon count to make itself more jagged, raising the Attack stat.'),
