(540, 'SING', 'Sing', 'NORMAL', 'Status', 0, 55, 15, 'NearOther', 'SleepTarget', 'CanProtect,CanMirrorMove,Sound', 0, 0, 'A soothing lullaby is sung in a calming voice that puts the target into a deep slumber.'),
(541, 'SKETCH', 'Sketch', 'NORMAL', 'Status', 0, 0, 1, 'NearOther', 'ReplaceMoveWithTargetLastMoveUsed', NULL, 0, 0, 'It enables the user to permanently learn the move last used by the foe. Once used, Sketch disappears.'),
(542, 'SLACKOFF', 'Slack Off', 'NORMAL', 'Status', 0, 0, 10, 'User', 'HealUserHalfOfTotalHP', NULL, 0, 0, 'The user slacks off, restoring its own HP by up to half of its maximum HP.'),
(543, 'SLEEPTALK', 'Sleep Talk', 'NORMAL', 'Status', 0, 0, 10, 'User', 'UseRandomUserMoveIfAsleep', NULL, 0, 0, 'While it is asleep, the user randomly uses one of the moves it knows.'),
