(545, 'SOFTBOILED', 'Soft-Boiled', 'NORMAL', 'Status', 0, 0, 10, 'User', 'HealUserHalfOfTotalHP', NULL, 0, 0, 'The user restores its own HP by up to half of its maximum HP. May also be used in the field to heal HP.'),
(546, 'SPLASH', 'Splash', 'NORMAL', 'Status', 0, 0, 40, 'User', 'DoesNothingUnusableInGravity', NULL, 0, 0, 'The user just flops and splashes around to no effect at all...'),
(547, 'SPOTLIGHT', 'Spotlight', 'NORMAL', 'Status', 0, 0, 15, 'NearOther', 'RedirectAllMovesToTarget', 'CanProtect', 3, 0, 'The user shines a spotlight on the target so that only it will be attacked during the turn.'),
