(549, 'STUFFCHEEKS', 'Stuff Cheeks', 'NORMAL', 'Status', 0, 0, 10, 'User', 'UserConsumeBerryRaiseDefense2', NULL, 0, 0, 'The user eats its held Berry, then sharply raises its Defense stat.'),
(550, 'SUBSTITUTE', 'Substitute', 'NORMAL', 'Status', 0, 0, 10, 'User', 'UserMakeSubstitute', NULL, 0, 0, 'The user makes a copy of itself using some of its HP. The copy serves as the user''s decoy.'),
