(553, 'SWALLOW', 'Swallow', 'NORMAL', 'Status', 0, 0, 10, 'User', 'HealUserDependingOnUserStockpile', NULL, 0, 0, 'The power stored using the move Stockpile is absorbed by the user to heal its HP.'),
