(614, 'HEARTSTAMP', 'Heart Stamp', 'PSYCHIC', 'Physical', 60, 100, 25, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove', 0, 30, 'The user unleashes a vicious blow after its cute act makes the foe less wary. It may also cause flinching.'),
(615, 'CONFUSION', 'Confusion', 'PSYCHIC', 'Special', 50, 100, 25, 'NearOther', 'ConfuseTarget', 'CanProtect,CanMirrorMove', 0, 10, 'The target is hit by a weak telekinetic force. It may also leave the target confused.'),
(616, 'STOREDPOWER', 'Stored Power', 'PSYCHIC', 'Special', 20, 100, 10, 'NearOther', 'PowerHigherWithUserPositiveStatStages', 'CanProtect,CanMirrorMove', 0, 0, 'The user attacks with stored power. The more the user''s stats are raised, the greater the damage.'),
(617, 'MIRRORCOAT', 'Mirror Coat', 'PSYCHIC', 'Special', 1, 100, 20, 'None', 'CounterSpecialDamage', 'CanProtect', -5, 0, 'A retaliation move that counters any special attack, inflicting double the damage taken.'),
(618, 'PSYWAVE', 'Psywave', 'PSYCHIC', 'Special', 1, 100, 15, 'NearOther', 'FixedDamageUserLevelRandom', 'CanProtect,CanMirrorMove', 0, 0, 'The target is attacked with an odd psychic wave. The attack varies in intensity.'),
(619, 'AGILITY', 'Agility', 'PSYCHIC', 'Status', 0, 0, 30, 'User', 'RaiseUserSpeed2', NULL, 0, 0, 'The user relaxes and lightens its body to move faster. It sharply boosts the Speed stat.'),
(620, 'ALLYSWITCH', 'Ally Switch', 'PSYCHIC', 'Status', 0, 0, 15, 'User', 'UserSwapsPositionsWithAlly', NULL, 2, 0, 'The user teleports using a strange power and switches its place with one of its allies.'),
(621, 'AMNESIA', 'Amnesia', 'PSYCHIC', 'Status', 0, 0, 20, 'User', 'RaiseUserSpDef2', NULL, 0, 0, 'The user temporarily empties its mind to forget its concerns. It sharply raises the user''s Sp. Def stat.'),
(622, 'BARRIER', 'Barrier', 'PSYCHIC', 'Status', 0, 0, 20, 'User', 'RaiseUserDefense2', NULL, 0, 0, 'The user throws up a sturdy wall that sharply raises its Defense stat.'),
(623, 'CALMMIND', 'Calm Mind', 'PSYCHIC', 'Status', 0, 0, 20, 'User', 'RaiseUserSpAtkSpDef1', NULL, 0, 0, 'The user quietly focuses its mind and calms its spirit to raise its Sp. Atk and Sp. Def stats.'),
(624, 'COSMICPOWER', 'Cosmic Power', 'PSYCHIC', 'Status', 0, 0, 20, 'User', 'RaiseUserDefSpDef1', NULL, 0, 0, 'The user absorbs a mystical power from space to raise its Defense and Sp. Def stats.'),
(625, 'GRAVITY', 'Gravity', 'PSYCHIC', 'Status', 0, 0, 5, 'BothSides', 'StartGravity', NULL, 0, 0, 'Gravity is intensified for five turns, making moves involving flying unusable and negating Levitation.'),
