(627, 'GUARDSWAP', 'Guard Swap', 'PSYCHIC', 'Status', 0, 0, 10, 'NearOther', 'UserTargetSwapDefSpDefStages', 'CanProtect,CanMirrorMove', 0, 0, 'The user employs its psychic power to switch changes to its Defense and Sp. Def with the target.'),
(628, 'HEALBLOCK', 'Heal Block', 'PSYCHIC', 'Status', 0, 100, 15, 'AllNearFoes', 'DisableTargetHealingMoves', 'CanProtect,CanMirrorMove', 0, 0, 'For five turns, the foe is prevented from using any moves, Abilities, or held items that recover HP.'),
(629, 'HEALPULSE', 'Heal Pulse', 'PSYCHIC', 'Status', 0, 0, 10, 'Other', 'HealTargetHalfOfTotalHP', 'CanProtect,Pulse', 0, 0, 'The user emits a healing pulse which restores the target''s HP by up to half of its max HP.'),
(630, 'HEALINGWISH', 'Healing Wish', 'PSYCHIC', 'Status', 0, 0, 10, 'User', 'UserFaintsHealAndCureReplacement', NULL, 0, 0, 'The user faints. In return, the Pokémon taking its place will have its HP restored and status cured.'),
(631, 'HEARTSWAP', 'Heart Swap', 'PSYCHIC', 'Status', 0, 0, 10, 'NearOther', 'UserTargetSwapStatStages', 'CanProtect,CanMirrorMove', 0, 0, 'The user employs its psychic power to switch stat changes with the target.'),
(632, 'HYPNOSIS', 'Hypnosis', 'PSYCHIC', 'Status', 0, 60, 20, 'NearOther', 'SleepTarget', 'CanProtect,CanMirrorMove', 0, 0, 'The user employs hypnotic suggestion to make the target fall into a deep sleep.'),
(633, 'IMPRISON', 'Imprison', 'PSYCHIC', 'Status', 0, 0, 10, 'User', 'DisableTargetMovesKnownByUser', NULL, 0, 0, 'If the foe knows any move also known by the user, the foe is prevented from using it.'),
(634, 'INSTRUCT', 'Instruct', 'PSYCHIC', 'Status', 0, 0, 15, 'NearOther', 'TargetUsesItsLastUsedMoveAgain', 'CanProtect', 0, 0, 'The user instructs the target to use the target''s last move again.'),
(635, 'KINESIS', 'Kinesis', 'PSYCHIC', 'Status', 0, 80, 15, 'NearOther', 'LowerTargetAccuracy1', 'CanProtect,CanMirrorMove', 0, 0, 'The user distracts the target by bending a spoon. It lowers the target''s accuracy.'),
(636, 'LIGHTSCREEN', 'Light Screen', 'PSYCHIC', 'Status', 0, 0, 30, 'UserSide', 'StartWeakenSpecialDamageAgainstUserSide', NULL, 0, 0, 'A wondrous wall of light is put up to suppress damage from special attacks for five turns.'),
(637, 'LUNARDANCE', 'Lunar Dance', 'PSYCHIC', 'Status', 0, 0, 10, 'User', 'UserFaintsHealAndCureReplacementRestorePP', 'Dance', 0, 0, 'The user faints. In return, the Pokémon taking its place will have its status and HP fully restored.'),
(638, 'MAGICCOAT', 'Magic Coat', 'PSYCHIC', 'Status', 0, 0, 15, 'User', 'BounceBackProblemCausingStatusMoves', NULL, 4, 0, 'A barrier reflects back to the target moves like Leech Seed and moves that damage status.'),
(639, 'MAGICPOWDER', 'Magic Powder', 'PSYCHIC', 'Status', 0, 100, 20, 'NearOther', 'SetTargetTypesToPsychic', 'CanProtect,CanMirrorMove,Powder', 0, 0, 'The user scatters a cloud of magic powder that changes the target to Psychic type.'),
(640, 'MAGICROOM', 'Magic Room', 'PSYCHIC', 'Status', 0, 0, 10, 'BothSides', 'StartNegateHeldItems', 'CanMirrorMove', 0, 0, 'The user creates a bizarre area in which Pokémon''s held items lose their effects for five turns.');
