(718, 'SCALD', 'Scald', 'WATER', 'Special', 80, 100, 15, 'NearOther', 'BurnTarget', 'CanProtect,CanMirrorMove,ThawsUser', 0, 30, 'The user shoots boiling hot water at its target. It may also leave the target with a burn.'),
(719, 'SNIPESHOT', 'Snipe Shot', 'WATER', 'Special', 80, 100, 15, 'NearOther', 'CannotBeRedirected', 'CanProtect,CanMirrorMove,HighCriticalHitRate', 0, 0, 'The user ignores any effects that redirect moves, allowing this move to hit the chosen target.'),
(720, 'WATERPLEDGE', 'Water Pledge', 'WATER', 'Special', 80, 100, 10, 'NearOther', 'WaterPledge', 'CanProtect,CanMirrorMove', 0, 0, 'A column of water strikes the target. When combined with its fire equivalent, it makes a rainbow.');
