(721, 'WATERFALL', 'Waterfall', 'WATER', 'Physical', 80, 100, 15, 'NearOther', 'FlinchTarget', 'Contact,CanProtect,CanMirrorMove', 0, 20, 'The user charges at the target and may make it flinch. It can also be used to climb a waterfall.'),
(722, 'RAZORSHELL', 'Razor Shell', 'WATER', 'Physical', 75, 95, 10, 'NearOther', 'LowerTargetDefense1', 'Contact,CanProtect,CanMirrorMove', 0, 50, 'The user cuts the foe with sharp shells. It may also lower the target''s Defense stat.'),
(723, 'BRINE', 'Brine', 'WATER', 'Special', 65, 100, 10, 'NearOther', 'DoublePowerIfTargetHPLessThanHalf', 'CanProtect,CanMirrorMove', 0, 0, 'If the target''s HP is down to about half, this attack will hit with double the power.'),
(724, 'BUBBLEBEAM', 'Bubble Beam', 'WATER', 'Special', 65, 100, 20, 'NearOther', 'LowerTargetSpeed1', 'CanProtect,CanMirrorMove', 0, 10, 'A spray of bubbles is forcefully ejected at the target. It may also lower its Speed stat.'),
