(728, 'AQUAJET', 'Aqua Jet', 'WATER', 'Physical', 40, 100, 20, 'NearOther', 'None', 'Contact,CanProtect,CanMirrorMove', 1, 0, 'The user lunges at the target at a speed that makes it almost invisible. It is sure to strike first.'),
(729, 'BUBBLE', 'Bubble', 'WATER', 'Special', 40, 100, 30, 'AllNearFoes', 'LowerTargetSpeed1', 'CanProtect,CanMirrorMove', 0, 10, 'A spray of countless bubbles is jetted at the opposing team. It may also lower the targets'' Speed stats.'),
(730, 'WATERGUN', 'Water Gun', 'WATER', 'Special', 40, 100, 25, 'NearOther', 'None', 'CanProtect,CanMirrorMove', 0, 0, 'The target is blasted with a forceful shot of water.'),
(731, 'CLAMP', 'Clamp', 'WATER', 'Physical', 35, 85, 15, 'NearOther', 'BindTarget', 'Contact,CanProtect,CanMirrorMove', 0, 0, 'The target is clamped and squeezed by the user''s very thick and sturdy shell for four to five turns.'),
(732, 'WHIRLPOOL', 'Whirlpool', 'WATER', 'Special', 35, 85, 15, 'NearOther', 'BindTargetDoublePowerIfTargetUnderwater', 'CanProtect,CanMirrorMove', 0, 0, 'Traps foes in a violent swirling whirlpool for four to five turns.'),
(733, 'SURGINGSTRIKES', 'Surging Strikes', 'WATER', 'Physical', 25, 100, 5, 'NearOther', 'HitThreeTimesAlwaysCriticalHit', 'Contact,CanProtect,CanMirrorMove,CannotMetronome', 0, 0, 'Hits three times in a row with mastery of the Water style. This attack always deals critical hits.'),
(734, 'WATERSHURIKEN', 'Water Shuriken', 'WATER', 'Special', 15, 100, 20, 'NearOther', 'HitTwoToFiveTimesOrThreeForAshGreninja', 'CanProtect,CanMirrorMove', 1, 0, 'The user hits the target with throwing stars 2-5 times in a row. This move always goes first.'),
(735, 'AQUARING', 'Aqua Ring', 'WATER', 'Status', 0, 0, 20, 'User', 'StartHealUserEachTurn', NULL, 0, 0, 'The user envelops itself in a veil made of water. It regains some HP on every turn.'),
(736, 'LIFEDEW', 'Life Dew', 'WATER', 'Status', 0, 0, 10, 'UserAndAllies', 'HealUserAndAlliesQuarterOfTotalHP', 'CannotMetronome', 0, 0, 'The user scatters mysterious water around and restores the HP of itself and its allies.'),
(737, 'RAINDANCE', 'Rain Dance', 'WATER', 'Status', 0, 0, 5, 'BothSides', 'StartRainWeather', NULL, 0, 0, 'The user summons a heavy rain that falls for five turns, powering up Water-type moves.'),
(738, 'SOAK', 'Soak', 'WATER', 'Status', 0, 100, 20, 'NearOther', 'SetTargetTypesToWater', 'CanProtect,CanMirrorMove', 0, 0, 'The user shoots a torrent of water at the target and changes the target''s type to Water.'),
(739, 'WATERSPORT', 'Water Sport', 'WATER', 'Status', 0, 0, 15, 'BothSides', 'StartWeakenFireMoves', NULL, 0, 0, 'The user soaks itself with water. The move weakens Fire-type moves while the user is in the battle.'),
